local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["77:310221719"]="아그윈의 후손, 그는 마지막이 될 것입니다 수호자 티리스팔의 메디브"
rows["77:318009368"]="그래서 그들은 스파이어의 하위 부분에 어두운 철을 밀어 넣었습니다."
rows["77:319162709"]="공포의 혈신, 영혼약탈자 학카르가 패했군! 이제 더 이상 두려워할 필요 없어!"
rows["77:320942573"]="마 Dragon Soul는 마 Dragon Flights의 구슬 안에 안전합니다"
rows["77:320954453"]="이 마법은 물 속속을 줄 거야... 만약 상어에 부딪히면!"
rows["77:321220039"]="엘로타 노 샤드라$B거미의 신, 독의 어머니, 실크 댄서, 죽음의 사랑."
rows["77:328132124"]="당신은 |cFFFF4809|Hspell:116784|h[Heart of Fear]|h|r에 의해 선택되었습니다!"
rows["77:331232815"]="우의 집에 오신 것을 환영합니다. 태양이 항상 밝고 음식은 항상 뜨겁습니다!"
rows["77:349742977"]="당신의 마음은 |cFFFF0404|Hspell:124862|h[멸망의 비전]|h|r로 괴롭혀있다!"
rows["77:349929501"]="아직 군대를 이끌 수 있어?"
rows["77:35124610"]="곧 알게 될 거야 이 코디도르에서 쥐처럼 둥지를 틀어"
rows["77:352377111"]="여느 여신인 그린파우가 마녀가 아니라, 현실적인 자이드 조각을 만드는 거죠."
rows["77:353898122"]="이 땅을 보세요. 이제 평화와 탐험에 대해 이야기 할 때가 되었습니다."
rows["77:358930973"]="마샤, 도망쳐서 멀리 가야 돼"
rows["77:363997171"]="전투에서 폭탄이 날아가서 난 살아남았지만..."
rows["77:36965788"]="엄마, 대아버지는 우리들을 지켜보고 우리가 괜찮다고 말해줬어"
rows["77:371219260"]="우리 세상말이 가까워지고 있습니다. 형제 자매 여러분! 아제로스 더 이상 없을 거야!"
rows["77:373119041"]="고마워요, 당신이 없었다면 내가 뭘 했는지 모르겠어요!"
rows["77:377276981"]="엔진이 다시 작동하고, 전속으로 움직입니다."
rows["77:378414075"]="그리즐은 휴대용 죽음의 광선을 줬어"
rows["77:37987803"]="음... 여긴 어디지? 이상하다. 바위돌기고릴라를 찾으라는 얘기 내가 하지 않았나? 했었나?"
rows["77:383951860"]="이 곳은 아름답지만 뭔가 잘못됐어"
rows["77:385365162"]="땅이 우리 발 아래에서 빠져나갔는데 내가 죽은 줄 알았어"
rows["77:389384935"]="자연은 마법과 평화롭게 살고 있습니다. 둘 다 우리의 미래에는 한계가 없습니다."
rows["77:390479951"]=" ⁇ 셈은 바로 앞이야 엘리트 공격력을 모았다"
rows["77:393553907"]="손가락을 느끼지 못하면 소방불을 조명하는 데 조심해야 합니다."
rows["77:397915097"]="Bile-O-Tron은 생으로 불어오면서 냄새가 나기 시작하죠."
rows["77:402166699"]="이제 기다려야 하네. 곧 있으면 보르샤가 낌새를 알아차리고 나타날 테니까..."
rows["77:410924240"]="마법 예술에 대한 능력이 있지만, 좀 더 정식적인 훈련을 받았으면 좋겠어요."
rows["77:41609814"]="이 협상 이후, 저는 긴 풍요로운 삶을 기대합니다."
rows["77:416838287"]="다음 마법을 너무 자유롭게 생각하게 하지 말아요 제사님"
rows["77:421622535"]="발라나르, 여기 임무를 훌륭히 수행하고 있군. 무척 기쁘구나."
rows["77:423703697"]="환영합니다. 다른 사람이 올지 확인하기 위해 몇 초만 기다려요."
rows["77:432682177"]="왜 캔드리스는 아직도 다르칸을 치러 가지 않을까요? 도대체 언제까지 기다려야 한답니까?"
rows["77:437527147"]="수천가지 이유가 있지만, 어떤 것이 싸워야 하는지 결정해야 합니다."
rows["77:440700954"]="아마 이 팀에서 가장 중요한 멤버가 내가야 paladin이니까"
rows["77:4425813"]="우린 널 해변에서 쫓아낼 거야 판다렌들은 우리 힘에 떨고 있을거야!"
rows["77:444007240"]="어둠, 부패는 아무도 알 수 없을 정도로 빨리 왔어"
rows["77:445345507"]="이 장벽을 유지하려면 집중이 필요해"
rows["77:446879054"]="화염으로 줄여서 곧 길네아스나  ⁇ 은 염물이 없어질 거야"
rows["77:44995305"]="아르헨트 Dawn의 요원들은 타나리스 사막에서 결정적인 승리를 거두었습니다."
rows["77:450520062"]="뭐? 아, 아니. 네가 무슨 말을 하든 상관없어. 난 그냥 고통 주는 게 즐거울 뿐이야."
rows["77:451539471"]="우리 민족의 신전과 사원을 보호하기 위해 최선을 다해야 합니다."
rows["77:469549376"]="강력한 힘! 느껴지는가, 필멸의 존재여? 어리석은 짓은 그만두고 내 편에 서라!"
rows["77:470830053"]="너희 동료에게 돌아가라. 계속 나아가서 파룬을 처치하고 전리품을 취하라고 일러라."
rows["77:47914005"]="자네에게 맡길 만한 일이 좀 있군. 시민 연락원에게 보고하게."
rows["77:481720363"]="저는 호드를 수년간 봉사로 존중했고, 이렇게 대우받았나요?"
rows["77:483525839"]="골격, 간단한 놀이이지만 여기서도 배울 수 있는 교훈이 있습니다."
rows["77:484355427"]="젠장! 여기서도 물고기가 안 무네. 그냥 예전 낚시터로 돌아가야겠다!"
rows["77:484644462"]="내 최신 발명품으로 너희 모두를 이길 거야!"
rows["77:486508853"]="저는 여행자 허브 전문가가 아닙니다. 저는 여전히 여러분의 일에 도움을 줄 수 있을까요?"
rows["77:492678541"]="우수 브루를  ⁇ 가 인고의 악성 해적들의 손목에서 구해줘"
rows["77:49870254"]="왜 내가 마녀를 위한 이 거칠고 약한 변명으로 갇혀있어야 했을까요?"
rows["77:506517302"]="더 이상 맥주를 마감하지! 오크 대장과 마지막으로 만났을 때 기억나?"
rows["77:525611526"]="내 말은, 여기 있는 건 다 처리할 수 있을 거고"
rows["77:527561007"]="여러분 덕분에 자원이 풍부해 있습니다."
rows["77:528245250"]="두 마리가 한 마리를 더 낫다면, 두 마리가 더 낫다는 건 뭐죠?"
rows["77:529239417"]="헤르메시우스, 내 엑소다르 패키지가 도착했나?"
rows["77:531253961"]="황혼 세계에서는 고통만이 있으리라! 자신 있다면 들어와 봐라!"
rows["77:536070101"]="이번엔 돌모아와 함께 싸우고 있다는 소식은 정말 좋네요"
rows["77:536523624"]="대군주 모르고르, 마침내 그대를 만나게 되었군요..."
rows["77:540217733"]="눈먼 채로 걷고 어두운 광산으로 큰 돌을 들고"
rows["77:540333607"]="** 목표 잠금 확인, 전쟁 승마 부대 도착, 항공 공격 임박**"
rows["77:541230387"]="내 협상자 자리를 놓쳤어 사실, 그는 죽었을지도 몰라"
rows["77:542311969"]="얼라이언스은 거미와 왜기를 우리에게 보내요?"
rows["77:545278609"]="이 테스트는 간단합니다. 당신이 해야 할 일은 돌을 때릴 때까지 돌을 때리는 것입니다."
rows["77:548880454"]="넌 나야, 하지만 미래에서 온 거야"
rows["77:55176022"]="네가 승리했다고 생각하니? 다시 생각해봐! 내 새로운 형태 앞에 서서 떨고 있어!"
rows["77:559121209"]="자넨 아직 내 왕이 아닐세! 설령 왕이었다 한들 그런 명령은 따를 수 없네!"
rows["77:573540714"]="저는 이해가 불가능한 수치심을 느끼고 있습니다. 저를 용서해 주십시오. 제 생각은 제 자신의 것이 아니었습니다."
rows["77:591507964"]="닭 깃털을 입고 있는 마모트!"
rows["77:593824215"]="다지크는 내게 사냥하는 법을 가르치려 했는데, 난 내 식대로 할 때 더 잘해."
rows["77:594792058"]="썩은 조각을 잘라내야 돼 내 작품에는 가장 좋은 부품만 들어갑니다!"
rows["77:606454051"]="위험은... 함정이... 이 결정적인 순간에 우리를 위해 조심스럽게 놓인 것 같습니다."
rows["77:607832866"]="붉은십자군은 이렇게 끝나지 않을 것이다! 우리 방어선을 뚫지는 못해!"
rows["77:610451811"]="긴급 차단을 막아야 한다! 캘타스 님께서 이 일을 알게 되시면 우릴 가만두지 않으실 것이다!"
rows["77:61288691"]="너무 많은 진흙이 있어, 변신이 너무 어두워지고  ⁇ 어질 거야"
rows["77:616888051"]="항상 자이드 색을 좋아했어요. 숲처럼 녹색이죠."
rows["77:625964066"]="내 신성한 도서관은 샤에게 점령되었습니다!"
rows["77:628278907"]="이 미친 짓을 멈추는 시간이 있어"
rows["77:628441894"]="그 물건의 모습으로 보면, 나는 상어들과 함께 수영을 할 수도 있습니다!"
rows["77:629586353"]="지금 얘기하는 거니까, 난 '마블라이트'를 데려가요."
rows["77:640048960"]="내가 듣고 싶은 건 다 내 피로 피겨서 돌아갔어"
rows["77:640391445"]="이 벽을 무너뜨리고 그 밖의 땅을 삼킬 거야"
rows["77:64795633"]="스파크, 어떻게 그럴 수 있었지?"
rows["77:674088133"]="신사 숙녀 여러분! 그... 뭐랄까, 이번 시합은 놓치지 않는 게 좋을 겁니다!"
rows["77:684482934"]="제가 정직한 고블린이었다면, 이 맥주가 축제 최고의 맥주라고 말했을 겁니다..."
rows["77:687973742"]="우리 셋을 봐요 옛날의 모래로 돌아가 듀로타옛날처럼 될 거야"
rows["77:689067321"]=" ⁇  부, 내장 안을 지켜봐."
rows["77:696276404"]="제주님, 제가 이 싸움에 참여하게 해주세요."
rows["77:697214881"]="파티를 하고 미스틱 버드하트를 초대하려고 했는데"
rows["77:698150236"]="심장이 깨진 것처럼 보이는데, 너무 슬프지 않은 순간 돌아와"
rows["77:699708502"]="그런데 슬프게도 성스러운 빛을 무시하고 죽을 운명 속에서 헤매는 이들이 있습니다."
rows["77:700635032"]="시장에서 장사가 잘 되나 보군. 지금 바로 배달을 다녀오리다."
rows["77:705281206"]="멋진데, 너 मेहनती가 아니냐?"
rows["77:712147015"]="내가 다시는 칼을 들고 다닐 수 없다고 맹세했지$B$B난 바보였어"
rows["77:714594438"]="%s]는 고백합니다. 저는 이 모든 이름들이 너무 많은 사도세자로 혼란스러워하는 것을 발견합니다."
rows["77:725669312"]="이 카드도 보셨나요? 이 카드는 정말 왜기를 의자에서 떨어뜨릴 겁니다!"
rows["77:726880157"]="일주일 내내 열심히 훈련했고, 내 노력은 승리로 보답할 것입니다."
rows["77:729572780"]="정말 웃기지도 않는군. 날 죽이려고 왔다는 강력한 알도르 군대가 고작 이 정도란 말이냐?"
rows["77:730299053"]="단단히 붙잡아, 거칠게 될거야 밤 엘프들을 조심해"
rows["77:745291513"]="진전을 이루고 있다고 믿나요? 스컬지!"
rows["77:751033338"]="그들은 당신을 괴물이라고 부르지요. 하지만 괴물은 당신이 아니라 바로 그들이랍니다. 잘 가세요, 스랄 님."
rows["77:753601241"]="여기서 우리는 원주민들에게 다가와 호드 공격은 통제됩니다."
rows["77:760318760"]="나에게서 아무것도 알아내지 못할 것이다, 비열한 놈. 나는 네 능력으로는 감당할 수 없는 존재이다."
rows["77:760711049"]="좋아! 좋아! 항복하지... 협조할 테니 무기는 내려놓으라고!"
rows["77:765966690"]="전 항상 당신께 빚진 채로, 내 조상들의 영혼을 안심시켜주셔서"
rows["77:769673645"]="진정해, 발드레드."
rows["77:772498353"]=" ⁇ , 후이저롱, 짐을 챙겨가"
rows["77:78450789"]="우리 중 누구도 살아남을 수 없다고 생각했지"
rows["77:789849021"]="망명자들의 피가 나를 힘으로 가득 차게 해"
rows["77:797324190"]="그거 이상하네... 저기서 잠깐이지만, 맹세코 네가 나를 땅딸보라고 하는 걸 들었단 말이지."
rows["77:798175870"]="오, 이제 당신이 그것을 한거야, 그것은 정말 정말 제대로 입력 코드가 아니었습니다."
rows["77:799798804"]="감히 주인님의 일을 방해하다니! 그 대가를 치르게 될 것이다, 이 어리석은 녀석!"
rows["77:800846554"]="트레이너가 여기 어딘가에 있어야 돼"
rows["77:802269746"]="오, 와요! 차가 부서지고 말이 신발을 잃었고 이제 화물이 망가졌어요!"
rows["77:802400094"]="그렇게 많은 힘을 가진 사람은 거의 없습니다."
rows["77:805455952"]="난 널 알아? 난 문제도 안해"
rows["77:80692130"]="우리 평화로운 땅 아래의 방에서, 오래된 신의 심장이 자고 있었습니다."
rows["77:811129551"]="하늘 경주란 무엇인가?"
rows["77:812958607"]="난, 그롬의 아들 가로쉬가 지옥의 불꽃이라고 부르는 것이 무슨 뜻인지 보여드리겠습니다!"
rows["77:836219143"]="우리는 당신의 고왕의 덕목에 대해 논의했습니다."
rows["77:85959914"]="안전한 곳에 거의 다 왔소. 여기서부터는 달려가도록 합시다. 너무 뒤처지지 마시오! 자, 갑시다!"
rows["77:864138711"]="|TInterface\\Icons\\inv_stone_10.blp:20|t %s |cFFFF0000 로크|r! 당신은 넥타이를 선택합니다!"
rows["77:865425720"]="슬픈 이야기는 아닙니다! 류랑은 \"좋은 삶을 사는 것을 결코 슬퍼하지 마십시오\".라고 말했습니다."
rows["77:885682084"]="멍청한 여자아, 내가 오래 전에 죽인 걸 찾고 있어"
rows["77:88795292"]="왜 날 쓸모없는 사람이라고 부르지?"
rows["77:890525886"]="%s]는 고백한다: 한 번은 레이 셰인을 대신 레이 시를 죽이려고 했다고 생각합니다."
rows["77:892804720"]="이 아타스라는 남자아이들은 '프로스트모어'라고 불리는 저주받은 칼을 가지고 있었습니다."
rows["77:895762128"]="우리는 반드시 그 주문을 찾아낼 거요. 그리고 놈을 소환해 해치우겠소."
