rows["77:940984664"]="다른 놀이를 찾아야겠군. 지금쯤은 48마리는 넘게 잡으셨길 바랐는데 말이오."
rows["77:944087694"]="그  ⁇ 은 놈의 숙주이고, 그를 묶어 놓아, 우리는 그의 몸에서 증오를 찢어 버릴거야!"
