rows["79:490303834"]="드롤과 함께요, 닥터 라버네와 함께 행복해 왜 우리를 분리하려 할까요?"
rows["79:490962686"]="새로운 타우카 동맹국들의 도움으로 노스렌드은 호드에 속할 것입니다."
rows["79:495454562"]="하지만 저는 우리가 가지고 있는 흉기에 대해 적어도 부분적으로 우리 탓이라고 주장합니다."
rows["79:496343330"]="전력을 다했고, 전 세계가 그의 것이었고, 그는 그것을 차지할 필요가만 있었다!"
