rows["80:1005199802"]="내 피로 이 은행의 안전을 보장해 줄 수 있어"
rows["80:1010712362"]="%s 그녀의 조언자가 귀에 속삭이는 것에 대해 무관심한 것 같습니다."
rows["80:1024160437"]="난 피곤해지네, 엘프들이 날 훔친 것처럼 취급하고 있어"
rows["80:1029565881"]="길고 긴 날 들에서 목마른 사람이 되죠, 내 말 이해가 되시나요?"
rows["80:1033240057"]="당신의 손에 의해, 이 산은 다시 꽃을 피울 것입니다. 그것은 보호하고 방어하는 것이 당신입니다."
rows["80:1035625727"]="%s은 광산  ⁇ 을 육지로 끌어당겨서, 분명히 피곤해 접근한다."
rows["80:1041386246"]="이 방의 힘은 원래 아제로스의 영원의 우물과 다르지 않습니다."
rows["80:1041842658"]="너보다 남자친구가 더 많았어"
rows["80:1056576871"]="진록, 내 빈디케이터 전투기의 일부를 되찾는데 도움이 필요해"
rows["80:1061503139"]="넌 너의 자부심을 비전을 뒤덮고 있어 타이탄 인형!"
rows["80:106273955"]="누군가 한 번도 나보다 앞서지 못하는 것 같소만. 꽤 힘들긴 했지만 난 48마리째 잡았다오."
rows["80:1076910965"]="내가 듣고 있어, 제 납치자가 아닐 것 같아."
rows["80:1080659026"]="브론즈베어드한테 무슨 일이 벌어지고 있어?"
rows["80:10829919"]="다시 깨졌어요? 내가 고칠게요... 하지만 보증금으로 이 걸 덮을 수 있을 거라고 생각하지 마세요.\010"
rows["80:1091607205"]="내 최신 발명품으로 너희 모두를 이길 거야"
rows["80:1093182377"]="이 가이스는 불안정한 조화를 만들 수 있습니다."
rows["80:1094827739"]="내가 복귀하면 좋겠어, 네가 필요한 건 아래로 갈 수 있어"
rows["80:109795214"]="친구들이 부딪힐 수 있다면 피라이트를 좀 가져오세요"
rows["80:1103087355"]="레이디 제이나가 알카스 섬을 조사하기 위해 기리폰을 사용하라고 했어요"
rows["80:1121752226"]="난 내 의문을 극복하고, 두려움과 분노를 극복했고,"
rows["80:1128654439"]="경쟁자 타바드 우승을 차지하고 있는 자랑스럽고 금메달을 따는 것 같아요"
rows["80:11323012"]="로코모티브는 움직이지 않지만 무기들은 갱신된 상태입니다"
rows["80:1132966155"]="내가 깨어났을 때, 클라크시가 당신에 대해 말해줬어"
rows["80:1135212729"]="자, 먹어라. 마지막으로 주는 식사로구나! 곧 림피 조를 죽인 자가 나 또한 끝장낼 테니 말이다..."
rows["80:11366900"]="이제 내 길을 떠나라, 불타는 군단를 다시 지하로 보내야 할 시간입니다!!"
rows["80:1139855387"]="무쇠 드워프는 피조물에게 질문할 수 없습니다. 파괴 작업을 진행합니다."
rows["80:114047838"]="여기는 실버문이 아닙니다! 여기가 어디죠? 아, 잠시 혼란스러웠어요."
rows["80:1149826138"]="내가 널 살려 두면, 그리모테마의 힘 앞에서 무릎을 꿇는 법을 배우게 될 거야"
rows["80:1153513074"]="조용히 지나갈 수도 있고, 아니면 싸워 갈 수도 있어"
rows["80:1155817346"]="한 친구가 맥주를 만들고 있는데 호프가 필요해요"
rows["80:1160408757"]="%s 공격 지점을 확인하지 못했고 미션이 중단됐습니다."
rows["80:1161113152"]="그 피그미 스 ⁇ 은 그들을 속이는 거야 적어도 잠시만"
rows["80:1166004496"]="네, 최선을 다해 네라락 왜 모두 검은색이고 연기가?"
rows["80:11673767"]="내가 갈 곳이 있고, 볼 사람이 있다는 걸 알 수 있지 않니?"
rows["80:1167930686"]="워치퍼 펠스크림이 네 머리를 잡을 거야 포세이큰!"
rows["80:1168383883"]="눈은 입술이 없지만 눈은 가르골에게 속삭인다"
rows["80:117212298"]="그들은 전 지역을 탐구하고 있습니다. 그들이 찾고 있는 것이 무엇인지 알아내야 합니다!"
rows["80:1187221666"]="물론 혼잣말이야. 이 도시에서 점잖은 대화를 나눌 수 있는 유일한 방법이지."
rows["80:1188557682"]="그것은 복수 도구인가? 그 백성의 미래를 창조하려는 의지가 있는가?"
rows["80:1188745263"]="동쪽에 늑대 무리가 출몰하여 말덴의 과수원에 살던 이들이 모두 당했소."
rows["80:1193365327"]="이런 마을에서 군인이 많은 곤경에 빠질 수 있습니다.$B$B많은 문제들이 있어"
rows["80:119765507"]=" ⁇ 은 미래를 봤어, 우린 함께 가야 돼 아니면 모두 어둠에 빠질 거야"
rows["80:1203054158"]="공원이 망가졌어 오늘 다른 길을 가야 돼"
rows["80:1203196922"]="블랙 테플의 옆에서 뛰어내려 저쪽에 뭐가 있는지 보아야 해!"
rows["80:1203791189"]="아만니, 구루바시, 모든 사람들이 각 부족으로 사명을 보내야 합니다. "
rows["80:1203842233"]="이 모든 일이 끝나면, 얼라이언스 명예표"
rows["80:1204800303"]="어떻게 초보자에게 비밀을 공유할 수 있을까요?"
rows["80:1219251825"]="얼음피 보초탑이 공격받고 있습니다! 저지하지 않으면 얼라이언스에 의해 파괴되고 말 것입니다!"
rows["80:1222128422"]="우리가 돌모아로부터 빨리 벗어날수록 더 좋죠"
rows["80:1223439427"]="좀 노력해야 하지만 이 피의 엘프의 목숨을 구할 수 있을 것 같아요"
rows["80:1224873209"]="오크의 시체는 보행길에 쓰레기가 나오지 않도록 부어 버렸습니다."
rows["80:1228252964"]="난 당신의 임무에 걸림돌이 될 지도 모르오. 난 저 분홍빛 인간들에게 잡히진 않을 것이니 걱정하지 말고 어서 가시오!"
rows["80:1229954782"]="멍청한 노예가 계속 싸워라 고레게크는 더 이상 발자국받지 않을거야"
rows["80:1239055038"]="도와줄게 좋겠지만 이해해줘요, 난 진짜 곤경에 처해있어요."
rows["80:1241349746"]="예언자는 신부로부터 힘을 훔치는 것을 어떻게 잘 처리할 수 있는지에 대해 명심합니다."
rows["80:1250939239"]="당신의 인내는 우리를 강하게 하고, 당신의 용기는 우리를 이끌고, 당신의 명예는 우리에게 영감을 줍니다."
rows["80:1253389275"]="네, 맞아요, 이봐요! 호드은 양똥의 무리가에요."
rows["80:1257767111"]="바로 그 이유 때문에 당신을 불러왔어요."
rows["80:1263765818"]="[ph]나로부터 허가를 사면 당신의 트로프에 접근이 허락될 겁니다."
rows["80:1265601050"]="이 불꽃은 수년 동안 계속 불타왔어요"
