rows["80:2060826444"]="저는 제 학생들의 모든 점들을 지켜보고 싶습니다. 여러분의 진전을 열망으로 지켜보겠습니다."
rows["80:2062753286"]="당신들의 지식이 부족해 질 때 다시 내게 돌아오세요"
rows["80:2065120855"]="괜찮아요, 하지만 제가 원하는 게 아니죠. 요리사가 내가 원하는 걸 알아야 할까요?"
