rows["80:2095532016"]="이 도시 내에서 여전히 선리버가 활동하고 있다. 얼라이언스와 호드는 함께 일하고 있다."
rows["80:2098856815"]="북쪽 싸움터를 생각하고 있소. 그대가 그토록 돌아가고파 하는 곳 말이오."
rows["80:21190990"]="실바나스, 우리 시체를 혼자 두면 내가 지금 당장 처리할 거야"
