rows["80:644760680"]="다시 인사합니다 다음 재판은 더 도전적이 될 겁니다"
rows["80:646913979"]=" ⁇ 을 열지 마$B$B이 괴물들은 내가 원하는 곳에 날 데려갔어"
rows["80:653417522"]="이건 이교도 문학입니다. 당신은 스톰윈드에 들어가는 유일한 방법은 연쇄로 있습니다."
rows["80:659123223"]="더 많은 거머리가 코타 베이스캠프로 곧 떠나게 될 거야"
rows["80:661431166"]="줄드락을 공략하려면 유능한 부하가 필요해, 친구. 진정한 힘을 다룰 줄 아는 자가 말일세."
rows["80:668321471"]="이 세포는 오래 안 지낼 거야 일리던의 머리가 어떻게든 갈거야"
