rows["80:695609348"]="아이미의 바퀴는 보통 달라란 은행 근처의 달라란 북부에 발견된다."
rows["80:697220706"]="목 좀 축이게 해달라는 이 늙은이의 청을 뿌리칠 텐가? 아... 별로 기대도 안 했어."
