rows["82:165747703"]="더 많은 맥주 필요해요 남서쪽 해적 배가 좋은 곳일지도 모릅니다"
rows["82:1664147107"]="당신의 인물이 치명적인 적들에 의해 학살되는 것을 보는 것은 어떻게 느껴지죠?"
rows["82:1666974270"]="이 사악한 유물이 어떻게 언데드와 관련이 있다는 것인지 이해가 되지 않네, 모그레인. 우리가 저 물건을 파괴해야 해!"
