rows["82:1714810770"]="이 열성 기염증으로 비행기가 자살로 다가왔어요"
rows["82:1725459593"]="미친 아이디어가 있을 수도 있지만, 영웅들의 도움이 필요할 겁니다!"
rows["82:1730662712"]="내가 명상하는 동안 저 생물들을 멀리 두면 곧 우리가 찾는 답을 얻을 수 있을 거야"
rows["82:1751517559"]="전투는 여전히 치열하고 비용이 많이 든지만 여러분의 도움이 귀중한 것으로 밝혀졌습니다."
rows["82:1763723128"]="더 나쁜 냄새가 나는지 모르겠어요. 발이나 치즈와 생선 필레가 똥으로 가득한 것 같네요."
