rows["84:1238726326"]="어디 한 번 그 얄팍한 전술을 다시 시도해 보시지그래, 얼간이 녀석들! 왜, 이제는 너무 겁이 나나?"
rows["84:124096880"]="비밀 다이어트, 코크텔, 꿈 같은 식습관을 소개해 드릴게요"
