rows["84:1341355812"]="더러운 놈! 이제 네 영혼을 수정 안에 가둬 내 임프에게 장난감으로 줘 버리겠다!"
rows["84:1345474728"]="캐스팅을 중단하십시오! %s는 |cFFFF0000|Hspell:139869|h[중개 조트]|h|r를 생성하고 있습니다."
rows["84:1346617318"]="고대 신이라... 그들이 토석인에게 육체의 저주를 걸었단 말이지... 에... 그래서?"
rows["84:1356875782"]="강인함을 잃지 마십시오. 캘타스 님께서 - 문제 발생 - 로르테마르 님께서 그대를 힘과 영광의 세계로 인도할 겁니다!"
