rows["84:1429841192"]="여기, 여기, 내가 지금으로 데려갈 수 있어"
rows["84:1431759269"]="캐스팅을 중단하십시오! %s는 |cFFFF0000|Hspell:139867|h[중개 조트]|h|r를 생성하고 있습니다."
rows["84:143309355"]="대부분의 증기 탱크는 작동하지 않고 산악인들도 빠르게 잃어가고 있습니다."
rows["84:1441877866"]="우리는 파멸의 갈림길에 서 있소. 이 성급한 행동에 대해 다시 생각해 봐야 하오."
rows["84:1442360654"]="우리는 모두 바엘 모단으로 매우 자랑스럽습니다. 칼림도어년] 최초의 왜성 정착지였습니다."
