rows["84:1460641262"]="도와줘! 마나 와이트, 형제들을 복수하고 그들의 본질을 훔치러 왔어!"
rows["84:1467020647"]="우리가 해냈어요! 저 지옥 같은 구덩이에서 저를 구해주셔서 정말 고마워요. 헤멧에게 제가 간다고 전해주세요."
