rows["84:1481346065"]="큰 퀴린이 문을 지키고 있는 것 같아서 조심해 깨우치지 말아"
rows["84:1495423375"]="대영주님, 은빛 서약단에서는 이번 행사에 참가자를 출전시킬 수 있어 기쁘게 생각합니다."
