rows["84:1515432336"]="전쟁 구역에 있는 불성스러운 사람들이 도시의 외곽에 있는 주요 건물 주변에 서 있습니다."
rows["84:1521909466"]="하지만 나에겐 속삭임들 들어요 혼란의 속삭임들... 심지어는 반대의 속삭임들도 들었어요."
rows["84:1537397041"]="킹스턴 전사군에 대한 폭탄 투입 임무에 있어"
rows["84:1540067322"]="안녕하세요, 아제로스 저는 더러운 세상과 재앙으로 가득한 세상을 남겨두고 있습니다."
rows["84:1547290761"]=" ⁇ 은 왜 다조에서 훈련을 계속하고 있어?"
