rows["84:1647333201"]="침입자! 그들을 태워라, 화염술사 이 이방인들에게 RAGNAROS의 불의 힘을 보여주십시오!"
rows["84:1649497841"]="경비 복부나 복부들이 열리는데, 당신은 더 높은 몸을 치고, 낮은 곳을 보지 않는다."
rows["84:1658335858"]="얼음날개 참호가 공격받고 있습니다! 저지하지 않으면 얼라이언스에 의해 파괴되고 말 것입니다!"
