rows["84:167908215"]="전력 수준은 충분해 보이지만, 마네포르지 울트리스에서 볼 수 있는 이상은 없습니다."
rows["84:169267735"]="고대의 신이시여, 간청합니다. 저희는 어떻게 해야 합니까? 이 땅의 신들을 구하려면 어떻게 해야 하겠습니까?"
