rows["84:1738340571"]="이 섬을 직접 보고 싶네요."
rows["84:1739831361"]="우리는 썬더브레이는 우리가 모든 영역에서 최고의 맥주 회사라는 것을 알고 자랑스럽게 생각합니다."
rows["84:1750241100"]="다행스럽게도 저는 배를 만드는 것을 좋아합니다. 이 해적들은 그것들을 폭발시키는 것을 좋아합니다."
rows["84:1753482017"]="괜찮아, 마지막을 지워야 돼"
rows["84:1759052264"]="세상에서 지저분한 쓰레기를 없애는 건 쉬운 일이 아니다, 낸시. 그래도 누군가 하지 않으면 안 될 일이지."
rows["84:1763820776"]="우리 장부에서 마라우돈 일족은 지워야겠어. 거래를 할 수가 있어야지, 원..."
