rows["84:1837298716"]="감히 학카리 성지에 발을 들여놓는 게냐? 학카르의 종들이여, 저 이단자들을 처단하라!"
rows["84:1839087939"]="드워프여, 이건 네가 낄 싸움이 아니다. 물러나지 않으면 그 배를 부술 수 밖에 없다."
rows["84:1840217644"]="지옥절단기를 만들어서 날 막으려던 네 눈물겨운 시도는 실패로 끝났다! 이젠 52번 구역의 차례다!"
