rows["84:1884950361"]="항상 우리 세상의 원자적인 영들이 유지하는 균형을 이해하려고 노력해"
rows["84:188634779"]="바다 바닥에 폭격을 계속 해 나가들에게 호드의 힘을 보여주세요!"
rows["84:1894172759"]="악마들의 서비스 대상은 이 곳의 에너지에서 마시는 것이었습니다."
rows["84:1895418263"]="그럼, 당신의 주머니에 있는 다이너마이트가 KS-L10 스틸스파크를 좋아할 수 있는지 보자."
rows["84:189881537"]="여기 누가 있는지 보십시오. 우리 친구, 주정뱅이 라리크입니다. 그의 어머니는 너무 뚱뚱해서 용 아가리에도 못 들어가지요."
