rows["84:1901465215"]="메그스가 실시한 마케팅 연구는 나가 침략이 임박하다는 것을 암시합니다!"
rows["84:1909022758"]="한 가지를 분명히 해봅시다. 당신은 올드 유언의 새끼일 수도 있지만 여전히 도시파입니다."
rows["84:1910271209"]="은행 밖에서 우편 상자가 있는데, 다르나서스의 중심에 있는 것입니다."
rows["84:1912610668"]="집에 있는 사람들이 이 사실을 알아내기 까지 기다려요!"
rows["84:191388930"]="영웅 여러분, 이 방들 아래에서 뭔가 잘못됐습니다."
rows["84:1922731580"]="클라벤은 좀비나 드론이나 뭐든 다룰 수 있을 만큼 돈을 내지 않아요"
rows["84:1929184652"]="앞으로의 전투는 전사의 실력을 시험하고 충성도도 시험해줄 것입니다."
