rows["85:291038803"]="죄송합니다, 지금 좀 바쁘게 있어요. 레이크샤이어에 베르너 오스고드에게 썰매를 만드는 것 "
rows["85:292687933"]="건방진 놈, 무례하게 군 대가를 톡톡히 받게 해 주마. 네 놈의 영혼은 내가 갖겠다!"
rows["85:294638434"]="여기 있는 대부분의 사람들은 \"스톰스타우트 맥주 공장\"보다 더 좋아해요"
rows["85:298135467"]="안디의  ⁇ 을 곧 만들겠군"
rows["85:300879426"]="트롤에게 먹여 주시오, 호르다임."
rows["85:302945993"]="마술사들의 왕국에 대한 당신의 통치는 밤새도록 이루어질 것입니다"
