rows["85:316962417"]="과연 소녀는 살아서 집에 돌아갈 수 있을까요? 그 답은 오직 시간만이 알려줄 것입니다. 이제... 연극을 시작하겠습니다!"
rows["85:318073701"]="우리는 군비 보관소를 통제했지만 섬에서의 우리의 작업은 아직 끝나지 않았습니다."
rows["85:324300551"]="무슨 일이 벌어지고 있어? 그들은 우리에게 아무 말도 하지 않았어! 그리고 난 화가 나기 시작했어!"
rows["85:331954306"]="왜 붉은십자군 보통 죽은자를 눈에 띄는 순간 죽인다"
rows["85:332071679"]="우린 이미 도시를 잃었어 왜 수도원에서 보강이 오지 않았어?"
rows["85:335550278"]="바리안은 그런 잔잔한 포도도 아닐까?"
rows["85:340895163"]="내 불꽃은 흔적조차 남지 않았구나. 죽음의 암흑이여, 내가 너에게 가노라."
rows["85:342806308"]="이제 또 다른 라운드에 준비됐어 준비해"
rows["85:358721468"]="우리 중 가장 어린 학생을 꺾고 이제 두 명의 최후학생과 맞닥뜨릴 거야"
rows["85:361342804"]="누구나 보스가 될 수 있는 건 아니잖아, 기술과 두뇌 그리고 물론 외모가 필요해"
rows["85:367875655"]="램 레이싱과 램 레이싱에 대해 더 많은 것을 배우고 싶으세요?"
rows["85:373339923"]="우린 말을 잃지 않을 거야, 보아라!"
rows["85:382258766"]="자만심은 세상의 종말을 불러올 뿐이다. 오너라! 건방진 피조물들이여! 와서 신의 진노에 맞서 보아라!"
rows["85:392462331"]="다리치고 물었고 씹었지만, 할 수 있는 일은 없었어요. $p!"
