rows["85:398043573"]="흥! 이 트롤플로우의 사정거리에만 들어오는 순간, 자네는 산산조각날 줄 알라고!"
rows["85:422244691"]="이곳에 청엽수 줄기가 있다고! 말하자면, 찾아주길 얌전히 기다리고 있는 황금 같은 거라고 할 수 있지!"
rows["85:442526764"]="안녕하세요 여행자, 저는 친절한 사람을 볼 수 있다고 생각하지 않았습니다 호드 이 해변에 얼굴을 올려다보죠."
rows["85:45105842"]="몸의 모든 상처는 배움과 패배가 성장할 기회입니다"
rows["85:462713871"]="어떻게 멸종된 생태계에 대해 알 수 있을까요? 식물이 독성적이죠!"
rows["85:464254876"]="고어게크 배고프다. 모닥불 위에 올라가라, 노예. 다 구워지면 말해라."
rows["85:467822305"]="아무도 위대한 밀하우스 마나폭풍의 뒤에서 웃고 이야기를 전하기 위해 살아가지 않습니다!"
