rows["85:475852302"]="보이지 않는 토끼, 여기저기 놓아주면 모든 걸 통제할 거야"
rows["85:485819445"]="좀 꽉 막았지만 여부는 바람이 날 수 있을 거야"
rows["85:48893495"]="도시 중앙 메사 위에 있는 바르조크 오크를 찾아봐요"
rows["85:493372569"]="오그르와의 싸움에 도움이 될 수 있는 조언은 무엇이든,"
rows["85:50993448"]=" 형제, 우린 다 망쳤어. (하지만 마스터... 나는 여전히 듣고있다... 너무 화가 난... 마스터...?)"
rows["85:510149343"]="네가 우리에게 준 도움이나 나를 구한 수치심을 잊지 않을 거야, 영웅"
