rows["85:572277948"]="잘 들어봐 스컬지 내가 서 있는 동안 너희들 중 누구도 선웰에 도달하지 못할 거야!"
rows["85:57325562"]="여기가 아버지를 해방시키기 위해 모든 것을 희생한 곳이고, 이제 내가 와서 파괴하려고 왔어."
rows["85:584660703"]="모두 터널에 있어 우리 경비해야 돼"
