rows["85:616208985"]="이상한 괴물이야, 평화적인 의도로 내 마을에 오는가?"
rows["85:630740934"]="무쇠 드워프는 이렇게 생긴 상자에 도구를 보관합니다. 천막 근처에서 찾아보세요."
rows["85:645399104"]="여기 부자가 있을 거야... 오, 보스, 네가 원하는게..."
rows["85:65051012"]="바람의 정령들이 내 부름에 응했다. 회오리바람이 우리를 무사히 내려다 주리라. 이제 뛰어라!"
rows["85:664329107"]="저 멀리 있는 건 뭐야? 배구? 아홉일째 덫에 걸려있어요! 도와주세요!"
rows["85:678251608"]="어렸을 적도 똑똑하니까, 길을 찾을 수 있어"
rows["85:678563637"]="돌난로 참호가 공격받고 있습니다! 저지하지 않으면 호드에 의해 파괴되고 말 것입니다!"
rows["85:68676662"]="테이블에 몇 개의 물품이 놓여있어서, 당신은  ⁇ 의 피부를 시작하기로 결정합니다."
rows["85:695919811"]="명령만 내려주십시오, 장군님. 임의로 운용하실 수 있는 2개 연대 병력을 한 달 내로 준비하겠습니다."
rows["85:703552314"]="좀 자면 좋겠네, 내가 너한테 일할게 있어"
