rows["85:739202316"]="난 괴물들이 장신품만 팔고 스스로 폭파하는 것 같아"
rows["85:75403167"]="달라란의 안정주님은 달라란 북동부 마직 마이너리 안에 있습니다."
rows["85:754862498"]="또 다른 벽이 있는데... 이 곳을 홈이라고 부르는 사람들로 구성되어 있습니다."
rows["85:755025870"]="흑마법사여, 네가 이해하지도 못하는 마법을 가지고 장난을 쳐서야 쓰나... 바로 이런 꼴이 되어 버렸지 않는가!"
rows["85:760634172"]="이 곳은 죽음 냄새가 나고 있어$b$b카자스처럼  ⁇ 을 채우기 전에 떠나야 해\010"
rows["85:763056594"]="너희 가족들이 널 이렇게 볼 수 없지 마, 우리 광부들은 서로를 돌봐야겠어!"
rows["85:771536581"]="그래, 그들은 조금 더  ⁇ 거렸어 그래서 내가 처리했어"
