rows["85:784620924"]="내 외치는, 릴리 울리는 모든 것은 헛된 일이야"
rows["85:793077848"]="심판의 날이 가까왔고, 당신 마음속에 정의가 유일한 진정한 길이라고 알고 있습니다."
rows["85:796976919"]="우리 아버지는 가까이 있어, 내가 알아, 우린 그들의 방어선을 깨고 그를 구해야 돼!"
rows["85:80559148"]="대사령관이 내 고통에 대해 알고 있잖아요?"
rows["85:825297409"]="네가 이렇게 하면, 나는 고르시크를 세계 기둥의 조각으로 성전으로 보내겠다."
rows["85:84771352"]="조용해, 작은여, 이 고대 땅이 말하는 걸 들을 수 있어 고통으로 울고 있다"
rows["85:858811941"]="살려 싸우세요, 친구들!"
