rows["85:894790494"]="저는  ⁇ 보어어의 몇 마디만 이해하지만, 들은 것은 마음에 들지 않았습니다."
rows["85:898873638"]="우리가 그 섬을 잃게 되면 호드 그리고 스톰윈드거의 사라진 것 같고, 그들은 그걸 알고 있습니다."
rows["85:900948122"]="날 나쁜 모습으로 만들려고 하는 거야?"
rows["85:901317699"]="난 로데론을 지킬 뿐이다. 네가 무슨 짓을 해도 날 막을 수는 없어."
rows["85:90446385"]="그건 못생긴 말이지, 난 배설기를 설명하는데 쓰일 단어야"
rows["85:906227149"]="쓸데없는 참견도 이걸로 끝이다. 내가 널 쓰러뜨리고 나면 메카조드 님이 저주를 풀어주실 것이다."
rows["85:928930157"]="쓸모없어 내 앞에 허벅지게 쓰러져 죽어라, 비참한 곤충아! 네 종류는 내게 쓸모없다!"
rows["85:929164606"]="전쟁에 들어갔을 때, 벨의  ⁇ 음 소리가 레이  ⁇ 의 전사들의 마음을 자극했습니다."
rows["85:935063202"]="계속 기다려봐, 20명이 먼저 왔어"
rows["85:93957731"]="당신의 작은 승리는 헛되이였어 Twilight's Hammer의 힘은 절대적입니다!"
rows["85:942449221"]="지금 대답하면, 당신만의 깨달음을 거부할 것입니다."
rows["85:9442744"]="[펄볼그어] 멀리까지 믹식 탁 너 가라. 강을 키취칼 자세히 보라. 따라오너라. 요르까지 일로그."
rows["85:947872308"]="우리 약사가 케모런을 볼 수 있어요"
rows["85:959084392"]="남쪽에서 모래 폭풍이 오고 있어, 이봐요..."
rows["85:969734609"]="그러다 그에 따른 진동수 변경으로 흐름에 마법적인 영향을 미치면 어쩌죠?"
