rows["85:977223059"]="경비대장님, 이제 떠나겠습니다. 마침내 훈련에 계속 가겠습니다!"
rows["85:986879031"]="얼음피 무덤이 공격받고 있습니다! 저지하지 않으면 호드에게 넘어갈 것입니다!"
rows["85:989189244"]="미안하지만 잠시 여기서 남아 있어야 돼 호드은 우리를 안전하게 지키고 있어"
rows["85:993896186"]="술 마시는 가장 좋은 부분은 취한 척 하는 것인데 난 남자처럼 행동하는 거야"
rows["85:996568383"]="어떡해, 저 놈들이 어디든 나오고 있어!"
rows["86:1019457321"]="언제 승마할 때 가장 좋은지 알려줘"
