rows["86:1063499533"]="내 집에 와서 내 사람들의 요구에 대해 짖는 것이 무슨 전략이야?"
rows["86:1076978693"]="으아!! 난 이제 말리고스의 노예가 아니다! 덤벼라, 끝장을 내주마!"
rows["86:1081247110"]="많은 젊은 판다렌 전사들이 이 무덤에 사라졌어요"
rows["86:1083314850"]="저는 항상  ⁇ 다라리들이 젊은 시절에 저를 행동하도록 만들어졌다고 생각했습니다."
rows["86:1090384860"]="침략자들은 빠르게 다가오고 있습니다."
rows["86:110267921"]="이봐, 호오! 오직 가장 용감한 판다렌만이 전 세계를 탐험하기 위해 류랑과 함께 해조리에게 합류했습니다."
rows["86:1129682170"]="이런 부정적인 감정들은 물리적 형태로 나타납니다. 우리는 이 어두운 에너지를 \"샤\"라고 부릅니다."
rows["86:1135708055"]="너한테는  ⁇ 을 수 있을 거 같아?"
rows["86:1138322614"]="대지크에게 큰 혀를 가진 털 없는 동물들이 우정을 맺는 것은 바보같습니다."
rows["86:115982211"]="지진이나 홍수나 다른 어떤 영들의 행위도 제 의무를 수행하는 것을 막을 수 없습니다."
rows["86:116268938"]="스파크마스터  ⁇ 은 조용히 당신을 쳐다보고"
