rows["86:117297348"]="길거리를 위한 물품이나, 전투를 지켜보는 동안 마실 수 있는 음료수?"
rows["86:1174122724"]="당신과 당신의 동반자들이 잠시 동안 여기 보이지 않는 것이 가장 현명해질 수도 있습니다."
rows["86:1176505397"]="도와주셔서 다시 한번 감사드립니다. 앞으로 평탄한 여행길이 되기를..."
rows["86:1176840798"]="비열하고 성가신 벌레들! 날 풀어다오. 최소한 자비로운 죽음을 선사할 테니!"
rows["86:1183224993"]="너 야생들이 내 최고 경영자가 빌라 근처에 오지 않도록 해"
rows["86:1188233559"]="Vrykul 저장소는 불에 타오르고 있습니다!"
rows["86:1192747113"]="예상대로군. 네가 올 줄 알았다. 위대하신 헬스크림도 함께 오셨군."
rows["86:1207866569"]="지킨다고? 왜? 그건 아무 의미도 없다. 그래, 그래, 그렇지... 사실은 빼앗고 싶지? 이젠 나도 알겠어!"
rows["86:1210651130"]="바로 저기 길이 있어... 우리와 저 연장 사이에는 끝 부분에 지뢰 몇 개만 있을 뿐이라고."
rows["86:1216737741"]="이번 설교 시간에 참석해 주신 모든 분들께 감사드립니다. 이렇게 친근한 얼굴들을 많이 뵙게 되다니 경이롭군요!"
rows["86:1231183247"]="아직은 너와 함께 돌아갈 수 없어, 레리사. 난 스컬지와 볼일이 남았거든."
rows["86:1234344914"]="신호 불을 켜야 돼, 보강이 없으면 게이트를 파괴할 거야"
rows["86:1235419046"]="피 흘리는 대신, 우리가 우리의 차이를 해결해..."
rows["86:124267958"]="전설의 홀이 서쪽의 강원도 위에 있는 거요"
rows["86:1244646532"]="그립온은 당신을 집중적으로 보고 옷에 익숙한 냄새를 맡고 있습니다."
rows["86:1246241399"]="우린 그들을 막았어 항구 상기에 뛰어들어 다른 배들을 도와줘"
rows["86:1246361854"]="우린 널 꺼낼 거야, 타레타 걱정 마 마 마술인이 너무 멀리 떠돌아다니는 건 의심이네"
rows["86:1248015340"]="위즐, 멍청이, 네가 입을 닫았으면 모든 게 괜찮을 거야!"
rows["86:1250412906"]="진수 씨가 죽게 될 수도 있어 $p빨리!"
rows["86:1250799428"]="반갑다, 렌사이, 호크마스터 누롱을 찾아왔어"
rows["86:1266709279"]="어떤 엔진도 이중 기화 포크링 증기 엔진만한 건 없지! 순수한 내화 석재를 연료로 하거든."
rows["86:1267369791"]="쓸모없는 괴물, 당신은 깃발이라고 부르는 이 캔들로 우리 집들을 청소하도록 명령할거야."
rows["86:1281940931"]="우린 언고로에 가젯잔의 이익을 보호하기 위해 왔고 그건 당신 문제 아니야"
rows["86:1287354905"]="난 여기서 탈출할 거야 그리고 내가 돌아왔을 때, 그것은 진주 전사군과 함께 될거야"
