rows["86:129849425"]="하지만 당신 같은 영웅들이 그의 무대에 있어 얼라이언스 이 일을 할 수 없습니다."
rows["86:1311846402"]="여기는 툰카로 야영지군요. 우리 형제가 다스리는 마을이지만, 당... 당신은 기억에 없습니다."
