rows["86:1328572731"]="위협 지수가 임계점을 돌파했습니다. 천체 기록을 중단합니다. 보안 수준이 상승했습니다."
rows["86:1329256890"]="다시 시작해보자, 이 기계를 착륙시키기 위해 필요한 것은 얼마일까요?"
rows["86:133100156"]="식물학에 대한 교육과 함께 유용한 물품을 제공할 수 있습니다.$B$B어떻게 도와드릴까요?"
rows["86:1348564649"]="저는 클라시세스로 돌아가서 이사회와 만나겠습니다. 코보크를 잘 돌봐주세요."
rows["86:1360260490"]="그 멍청한 크리켓은 날 밤에도 깨우치지 못해"
rows["86:136038138"]="영들은 우리의 발걸음을 인도합니다. 우리가 삶을 따라가는 동안, 어떻게 내가 당신의 길을 인도할 수 있을까요?"
rows["86:1364872804"]="네, 노그네포거 씨 그 거인에 대해 더 이상 걱정할 필요가 없을거야!"
rows["86:1366267133"]="다지크가 쓸모 있는 걸 또 알려주지! 등 긁는 데 수정을 써봤자 별 쓸모가 없다. 해보지 마라."
rows["86:1368190272"]="그 곳에서 저는 이 가슴을 내 손으로 만들어서 몇 시간 동안 가이에서 일했습니다."
rows["86:1374270285"]="니우자오의 일을 다 해냈어 이제 진짜 조사로 돌아가야 한다"
