rows["86:138253601"]="자연의 자식인 거라면 공원 내 달수리보다 더 이상 찾아볼 필요가 없어"
rows["86:1384226557"]="빛이시여, 그가 끔찍한 검의 차가운 손아귀에서 벗어나 평안하기를."
