rows["86:1418985345"]="여기는 내가 지킨다. 어느 누구도 비전술의 신비를 건드리지 못할 것이다."
rows["86:1421637617"]="소페라 나즈 근처에서 적의 활동이 보고되고 있습니다!"
rows["86:1426688191"]="으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!"
rows["86:1427977626"]="경보! 경보! 적들의 방어선 통과가 감지되었습니다! 수가 증가하고 있습니다."
rows["86:1435307732"]="상관없어 내가도 그들의 마음을 오염시키는 악을 느낄 수 있어"
rows["86:1440116561"]="걱정할 필요 없어, 보드장 \"관측자\"가 여기에 있어"
