rows["86:1448431391"]="오늘날에는 경쟁자들이 가득합니다. 여러분이 돌아서는 곳이라면 어디에서나 다툼을 보기 쉽습니다."
rows["86:1455050631"]="테라모어로 보내주시겠어요?"
