rows["86:1501814229"]="농부 윤은 그냥 사랑이야 내가 그에게 무엇을 해야 할지 계속 말해 주면, 그는 계속 그렇게 한다!"
rows["86:1504068294"]="일이 보이는 것처럼 거의 없어서, 제 아들이 이곳이 신성한 곳이라고 말해줬어요"
