rows["86:1522637179"]="이 지역을 Sentinel에게 확보하는 것은 페라라스의 방어의 마지막 부분일 것입니다."
rows["86:1525334934"]="귀여운, 당신은 올바른 신발 없이는 당신의 외모를 완성할 수 없습니다."
rows["86:1530727352"]="그 모든 배럴들 내 최고의 맥주 중 하나 적어도 영광의 불꽃으로 꺼졌어"
rows["86:1530816702"]="첸이 생각하는 맥주도 맛볼 수 있을 것 같아$b$b그 사람은 큰 게임이라고 말해요"
rows["86:1537917882"]="정말 예쁘네요, 제대로 훈련하고 다시 공중에 올라갈 때까지 기다릴 수 없어요"
rows["86:1546483976"]="어떻게 살아남을 수 있을까요? 호드 그리고 이 고대 악의 힘?"
rows["86:1551938949"]="%s 대행자 마브렌과 죽음의 스터커 몰테니스의 방향으로 칼을  ⁇ 니다."
rows["86:1556281511"]="날아가 있는 요새들을 다시 노스렌드로 데려가라, 내가 맨손으로 그들을 짓밟을 때까지!"
rows["86:1559696651"]="더 이상 너희는 호드당신의 목적은 망가졌어"
