rows["86:157549184"]="영원한 고통을 맛보게 해주마. 복수는 나의 것이니..."
rows["86:1576789014"]="이거 충분히 좋은지 모르겠지만, 우리가 장난을 치려고 하는 게 아닙니다."
rows["86:1581671077"]="고레게크는 산 위에 더 많은 빗물이 있는지 궁금합니다."
rows["86:1582038687"]="알리사저가 급속한 순환으로 날아오르고 강렬한 바람은 화염의 날개를 제거할 것이다!"
rows["86:1587649953"]="검은용군단이 느닷없이 나타나, 우리가 미처 손쓸 새도 없이 공격을 퍼붓더구나."
rows["86:1624184429"]="난 이 녀석을 다시 움직이게 해보겠어. 자넨 먼저 가보라고. 난 알아서 돌아갈 테니."
rows["86:1626383015"]="난 이런 경기에는 별 관심이 없소, 티리온 경. 그래도... 저들이 훌륭한 모습을 보여주리라 믿소."
rows["86:163245437"]="좀 더 단단히 해줘요, 재미를 놓치고 싶지 않아요"
