rows["86:1649867871"]="가짜 성기사야, 덤벼라! 성스러운 빛의 진실한 종이 내리는 분노를 맛보아라!"
rows["86:1663173008"]="크리스탈은 당신에게 새로운 능력을 부여해줬어"
rows["86:1675784648"]="'하일스크림' 호드 우두미술이 필요 없어 트롤 이제 내 시선을 벗어나"
rows["86:1677896399"]="이 미니어처들이 원작과 비슷하게 만들어졌다면, 당신은 기회를 잡지 못할 겁니다!"
