rows["86:1696228902"]="전 인정해야 할건 당신이 장군의 임무를 받았을 때 내가 기대했던 게 아니잖아요"
rows["86:1704094612"]="|c0087CEFA|Hspell:105845|h[핵 폭발]|h|r는 음반을 뚫을 만큼 가까이 오지 않았다!"
