rows["86:1711371616"]="카자로 산이 터졌다는 게 중요하지 않아 내가 꼭대기에 머물러야 한다는게 중요해"
rows["86:1711376956"]="우린 지금 당장 야라크스 신을 붙잡고 있지만 더 오래 구속할 수 없어요"
rows["86:1721137260"]="안녕하세요, 내 친구 왜 엄마와 아빠가 나를 돼지라고 부르지 않았는지 모르겠어요"
rows["86:1723803102"]="우리 영웅이 살아있다는 게 기쁘네요"
rows["86:1736042622"]="잘 들어라, 스컬지의 모독자들아! 내가 서 있는 한 너희 중 누구도 태양샘에 닿지 못한다!"
rows["86:176769370"]="경보폭탄 2600 고장. 자폭 절차 무효화. 작동 정지."
rows["86:1774717888"]="잘못된 곳으로 오시면 그 전문가인 고단과 얘기해 더 많은 것을 배우게 됩니다"
rows["86:1779713352"]="내 말을 들었어야 했어. 그랬다면 받아 마땅한 모든 칭찬이 내 몫이었을 텐데!"
rows["86:1781002035"]="아주 독특한 냄새가 있어 직경에는 그런 냄새가 없어"
