rows["86:1876711653"]="피가 이 세상에서 우리의 자리를 깎기 위해 지불하는 대가야"
rows["86:1876851559"]="우리 바위 위에 너희 집을 짓고 너희 무지함이 멸망하리라"
rows["86:1881941769"]="바람의 주자 멜'야크는 3 그의 동맹국들 중 무력하고 그들을 해방시켜!"
rows["86:1895547208"]="이 세상 의 기본적 인 영 들 이 유지 하는 균형 을 이해 하기 위해 노력 해야 합니다."
rows["86:1900367611"]="건방진 젖먹이! 죽고 싶어 안달이구나! 자, 보아라. 주인님께서 일어나신다!"
rows["86:1911111525"]="카르게시족은 왜 강인만이 우리 왕의 편에 서야 할 지 보여 줄 것입니다!"
rows["86:1912980875"]="우리는 세진 마을의 해안에서 모여 우리의 것을 되찾을 것입니다!"
rows["86:191507217"]="시간이 지나지 않아, 낯선 사람들 곧 당신이 구원하지 못한 사람들의 영혼에 합류할 거야"
rows["86:1918861244"]="바람의 주자 멜'야크는 4 그의 동맹국들 중 무력하고 그들을 해방시켜!"
rows["86:1929633654"]="조그만 심장 뛰는 소리가 들린다. 오, 점점 빨리... 곧 멈추게 해주마."
rows["86:1950151470"]="피르주스는 미치진 못했고, 리치 왕!"
rows["86:1951781172"]="입만 열면 그 소리군. 죽을 때까지 못 끝내는 건 아닌지 모르겠구먼."
rows["86:1954595431"]="가로쉬가 당신이 쌓은 부를 요구하고 있어"
rows["86:1957515246"]="날씨는 어떻게 되는지 모르겠어요 여기가 모두 회색이고 어두운 구름이 뒤돌아다니고 있습니다"
rows["86:1972287057"]="마지막 죄수를 죽여 내버려 두면 침입자들이 지금 어리석은 행동을 재고할지도 몰라"
rows["86:1975932062"]="오래전부터 늦은 일을 할 수 있도록 도와줄 사람을 찾고 있습니다.$B$B넌 능력이 있는 것 같아"
rows["86:1976793465"]="여기 주정뱅이 녀석들 중 하나가 아니라 나를 구하다니, 정말 탁월한 선택이었소."
rows["86:1979311165"]="우리는 방금 도착했고 이미 친구들 과 동료들을 묻어버렸어요"
rows["86:1981540722"]="이봐, 이제 봄과 삶에 즐거워할 때가 됐어"
rows["86:1985734944"]="그는 성장하고 성장하고 성장했습니다. 너무 커서, 이제 어떤 사람들은 그를 \"여보 섬\"이라고 부르죠."
rows["86:1985823499"]="항상 외계인이 언제 해안을 뚫을지 궁금했는데 이제 당신은 왔어요"
rows["86:1987961539"]="더 이상 조심해 얼라이언스만약 다시 공격하려 한다면 고통 받을 것입니다."
rows["86:1993520630"]="*sigh* 시묘를 다시 확인해야 할 시간입니다. 몇 분 후에 돌아올게요."
rows["86:2023220958"]="지금 그는 제정신이 아닐세. 세계가 파괴되는 동안 미쳐버렸지. 우리 정령들이 쉴 수가 없어."
rows["86:2030705326"]="자라잔의 시간은 끝나고, 에코 섬은 다시 다크스피어 부족의 소유가 될 것입니다!"
rows["86:2032388226"]="만약 인생에서 배울 수 있는 한 가지 있다면, 그것은 항상 더 많은 것을 배울 수 있다는 것입니다."
rows["86:2035910519"]="%s 그의 피가  ⁇ 기 시작하면서, 맹수들의 속임수가 그를 지나갈 때 지켜보죠."
rows["86:2037471856"]="보통 조용한 정류장인데, 이 모든 야롱들이 어디서 왔는지 보세요."
rows["86:2043653112"]=" ⁇ 버 폭탄을 겨냥해, 우리가 하나 발사하면 엄청난 폭발을 일으킬 거야!"
rows["86:2052267992"]="점장님, 우리 정신 마취 독에 죽음의 풀이 부족하다고 손님들이 항의하시는데요."
rows["86:2056234715"]="세라투스의 모조는 우리 것이다. 곧 모든 것이 드라카리의 힘 앞에 산산이 부서지리라!"
rows["86:206270859"]="나가의 노예제에서 해방됐고 내 의지는 다시 내 것이야!"
rows["86:2064192220"]="그 해안에서 우리는 정복할 것입니다 스톰윈드그리고 적의 희망도 함께"
rows["86:2069027097"]="난 모험가로 태어났지, 방랑 섬의 판다렌들처럼"
rows["86:2092509494"]="내 상처가 너무 크다 난 못 살겠어 우리 시민들이 구석에 갇혀 있어"
rows["86:209680780"]="빨리, 형제! 얼마나 더 오래 이 걸 수 있을지 모르겠어 스컬지 괴물들이 돌아왔어!"
