rows["86:2119352041"]="내 힘을 잃게 되면서 드래곤 영혼은 시간 속에서 원래의 자리에 돌아왔다."
rows["86:2120793592"]="|cFFFF2222[전기화]|r 당신은 근처의 라이트닝 스 Rod에서 전기를 방출 할 수 있습니다."
rows["86:2125958007"]="10천년 동안... 안개가 막힌 봉투가 파다리아를 호기심한 눈으로부터 숨겼습니다."
rows["86:2141287764"]="시간이 다가오고 있습니다. 이 땅을 휩쓸고, 우리를 대적하는 모든 사람들을 희생시키겠습니다!"
rows["86:2142979453"]="호르니즈! 나 돌아왔어! 날 도와주신 분도 곧 여기 올 거야."
rows["86:2146497286"]="왕의 스카우트는 잔다라리 트롤들이 왜성 수도를 위협한다는 것을 발견했다."
rows["86:215906707"]="아제로티아 고대 신, 추세 기조를 시도하는"
