rows["86:22062532"]="오늘 날 이길 수 있지만 천성들을 물리칠 수 있는 모든 덕목이 필요할 거야"
rows["86:225536630"]="대체 알레르기는 뭐예요? 그게 우리 야옹이랑 무슨 상관이 있다는 거지?"
rows["86:234735877"]=" ⁇ 루브에 오신 걸 환영합니다, 작은."
rows["86:237077252"]="그라쉬는 그 울리는 벨을 찾는데 인내심을 잃어 버립니다."
rows["86:237312124"]="바보가 되지 마, 볼진! 포위 무기가 없어! 이 전투에서 이길 수 없다!"
