rows["86:37140377"]="그들은 우리를 불문했고, Hell'scream's 호드를 불문했습니다. 전 마을 전체를 처형해야 했어야 했습니다!"
rows["86:387575456"]="마이크 메차치킨 한 마리가 있어 어떻게 이런 이름을 생각해낸지 모르겠어"
