rows["86:397617017"]="오늘 너무 잘 보이지 않아 햇빛이 뜨겁고 일찍 밝고 물에는 활동도 없다"
rows["86:40273466"]="전쟁터에서 참을성 있게 싸웠고 용기가 다시 시험될 거야"
