rows["86:449754638"]="에르디'루인은 아키몬데가 죽은 이후 주인이 없었고 이제 내가 그 주인이 될 거야"
rows["86:450914962"]="우리가 여기서 뭘 하고 있는거야? 우리는 이 섬에서 벗어날 수 있는 길을 찾아야 하지 않나요?!!!"
rows["86:451561095"]="당신들의 판단에 따라 군인들에게 분당을 줄 수 있지만 우리는 편을 선택하지 않습니다."
rows["86:45364347"]="고대의 존재께서 나의 손을 인도하시니... 잠에서 깨어나라! 깨어나서 이 저주받은 곳을 봉인하라!"
rows["86:457310680"]="침입자라니! 감히 내 취미 생활을 방해하는 놈들은 쓴맛을 단단히... 잠깐... 너는..."
rows["86:473195273"]="여기가 좀 불편하긴 하지만 여전히 카즈 모단으로 우리 집인 것 같아요"
rows["86:474856385"]="특히 부모들이 신이고 자녀들은 괴물일 때"
rows["86:496710601"]="아바스트, 이 얼라이언스 스칼리웨이가 우리 배에 도착해"
rows["86:49695552"]="저 망할 놈, 고엘 - 깨어 있어! 이렇게 끝나지 말아줘! 우린 너무 멀리 왔어 실패할 수 없어!"
rows["86:500202162"]="이 측정에 도움이 필요해요, 동료에게 신호를 보내요"
rows["86:50160497"]="당신은 바람을 타고 있는 뒤에서 세상을 내려다보기 전까지는 살지 못했습니다."
rows["86:524305464"]="두 번째 경비탑이 무너졌다! 마지막 경비탑을 파괴하면 적은 금세 퇴각할 것이다!"
