rows["86:549194609"]="나즈그림 장군은 당신과 당신의 승무원을 고용하도록 보냈습니다 칼림도어 봉쇄 함대"
rows["86:565711829"]="어둠의 주인께서 너의 부질없는 행동을 눈치채시고 죽음의 메시지를 전하기 위해 날 보내셨다!"
rows["86:57713032"]="늑대에게 싸움을 가져가자. 이 일은 너무 오래 지속됐습니다. 그들은 대가를 치러야 합니다."
rows["86:586385094"]="네 진짜 이름이라도 있다면, 네바락스, 네가 속옷을 입은 악마라는 비난이 있어!"
rows["86:589222419"]="훌륭해요, 요구된 매개 변수와 규격에 부합해요"
rows["86:592546706"]="원하는다면 메일스트롬에서 죽음의 날개가 파괴된 후의 결과를 보여드릴 수 있습니다."
rows["86:605361881"]="먼저 케잔, 그리고 이제 여기. 우리가 이 섬에서 빨리 벗어날 수 없다면 우리는 토스트입니다!"
rows["86:60993936"]="우리 계급의 학생들은 하늘 경주라고 불리는 공중 경쟁에서 속도를 시험합니다."
rows["86:632478386"]="고마워 친구, 좀 더 자란 거미들을 죽여보자"
rows["86:640258988"]="아니, 영, 그들은 모두 안에 갇혀있다고 두려워합니다."
rows["86:647019096"]="어두운 시간, 하지만 우리 사람들은 모든 좋은 위해 tha 호드에 머물게 될 것입니다.  "
rows["86:655624165"]="존스가 가는 곳엔 내가 갈 거야 그가 걸는 곳엔 내가 걸리지만 이번에는 뒤로 물러나야 한다고"
