rows["86:66139094"]="굴단이라... 아제로스에서는 그리 잘 알려지지 않은 이름이지.$B$B미안하지만 자네의 대답은 틀렸네."
rows["86:679559924"]="내가 여기 있어, 네가 내 말을 들을 수 있어"
rows["86:685151856"]="초대해줘서 고맙소, 티리온 대영주. 어떤 경기가 펼쳐질지 기대하고 있소."
rows["86:692961557"]="6에너지즈한 스택을 가지고 아카네 피널의 정상에 도달하여 실험을 완료하십시오."
