rows["86:701888692"]="이 곳은 거칠고 썩은 곳이지만, 여기 있는 모든 사람들은 내면적으로 부드럽습니다."
rows["86:709242305"]="이 발사기가 날 미치게 해줘요"
rows["86:709889896"]="정말 아쉬운데, 시네도레이는 드레네이 같은 괴짜들과 어울릴 수 없었어"
