rows["88:1267473383"]="그리고 끔찍한 늑대나, 거인이나, 그 이상하게 생긴 산양이 있는 곳은 싫어요!"
rows["88:1267821163"]="- 아뇨, 안보셨나요?\010후이는 그린스톤 퀘어리의 자드를 저주하고 그 괴물로 변신시켰습니다."
rows["88:1274833520"]="코바이는 우리를 위협했지, 그게 전부였어"
rows["88:1274837545"]="저라드  ⁇ 을 치면 다음엔 더 많이  ⁇ 게 해"
rows["88:1275988429"]="스컬지은 이 지구에 모든 생명을 종식시킬 무경기 기계입니다."
rows["88:1280483739"]="내 아빠는 항상 내 머리에 눈이 있다고 말했지"
rows["88:12844800"]="거렁이들이 다시 드래그와 그림자의 틈을 청소할 때가 된 것 같습니다."
rows["88:1298142849"]="파괴, 지배, 단결, 미묘하게 분해!"
rows["88:1311102874"]="아직 간단한 마법도 잘 못해  ⁇ 돌토스를 괴롭히세요"
rows["88:1316254321"]="이제 용서를 빌고, 내가 여전히 당신을 살게 할 수 있습니다."
rows["88:1320889475"]="나쁘지 않겠지만, 추가적인 교육은 해를 끼치지 않을 것 같네요."
rows["88:1331510652"]="난 널 도와줄 때로 지쳤어 전투장에서 해결해야 할 시간이야"
rows["88:1340801319"]="좋다. 저 하등한 생명체들을 처리해 주지. 잠깐 귀찮을 뿐이다. 죽을 준비나 해라!"
rows["88:1342983230"]="영웅들, 탑을 가져오세요. 총을 그 원동생 드래크에 올려서 하늘로부터 폭발해 주세요!"
rows["88:1354247976"]="뭔가 매우 성가실 것 같은 녀석들이 있습니다. 그자들이 시간의 길을 건너는 모습이 보이고 있군요."
rows["88:1355653496"]="포세이큰 마차가 부서져 버리다니, 믿을 수가 없어. 이제 이 땅에서는 좋은 일이라고는 일어나지 않는군..."
rows["88:1359426133"]="잘했다, 보병! 더러운 호드 짐승들이 우리 앞에 모습을 드러내는 꼴을 그냥 두지 않으려던 참이었다!"
rows["88:1362104627"]="아마 당신은 당신의 던지기 팔을 연습하기 위해 근처의 용에 던져 보아야 합니다."
rows["88:137140288"]="이 판다레네들은 충분히 지혜로운 사람들이죠. 호드."
rows["88:1382699588"]="하지만 넌 블랙 드래곤이야 그리고 내 형제 자매들의 부패를 공유하고 있어"
rows["88:1388352999"]="나의 왕궁을 더럽힌 스컬지가 사라졌군. 그대들은 가도 좋다."
rows["88:1388566043"]="괜찮은 일이지만, 네가 내게서 일을 해준다면 더 인상적일 거야"
rows["88:1391670299"]="다른 구석에... 내 친구 프랜이 있고, 그 마운트를 가지고 왔어!"
rows["88:1398902659"]="이 승리는 값비싼 것이지만 훨씬 더 나쁜 일이 될 수 있었습니다."
rows["88:1405614071"]="얼음피 무덤이 공격 받고 있습니다! 저지하지 않으면 얼라이언스에게 넘어갈 것입니다!"
rows["88:140719843"]="%s은 |cFFFF0000|Hspell:138644|h[Siphon Anima]|h|r로 다른 고렘에서 전력을 배출한다!"
rows["88:1423343119"]="내 선물을 여러분과 나누기 전에 당신의 결단력을 증명해 주어야 합니다."
rows["88:1425287182"]="리벤우드와 지알르브론에 이렇게 가까이 도착하는 것은 실수일지도 모릅니다."
rows["88:142723769"]="여기 오는 데 너무 오래 걸려서 미안합니다. 프라우드무어 님께서도 함께하셔야 할 것 같아서 말입니다."
rows["88:143628626"]="좋을 대로 하시오. 하지만 안에 들어가려거든 최소한 세 명은 나를 도와야 하오. 따라오시오..."
rows["88:1458274889"]="호드가 깊은무쇠 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!"
rows["88:1466350564"]="우린 준비됐어, 하이글로드 아제로스- 왜? 빛 새벽에"
rows["88:146779968"]="케케크가 큰 혀의 새끼들의 좋아하는 장난감을 가져갔어"
rows["88:1470612871"]="이럴 때도 내가 똑같을지 모르겠지만"
rows["88:14739534"]="안녕하세요, 육아, 나부드입니다."
rows["88:1478690658"]="내가 얼마나 자주 죽여야 할지 상관없어... 이 땅을 구하기 위해 너희 모두를 데려가겠다!"
rows["88:1485625799"]="타란 주, 우리의 발걸음은 안전해 공격의 첫 기회를 잡아야 해"
rows["88:1486147103"]="마음을 단단히 먹게, 영웅들이여. 두 배의 공포, 산성아귀와 공포비늘이 투기장으로 들어온다네!"
rows["88:1494040950"]="이 동굴에 가는 그룹에 합류하세요. <이번 선택은 당신을 회의석 줄을  ⁇ 게 합니다>    \010"
rows["88:1498546323"]="저는 이것을 기대하고 있습니다. 백 호랑이는 파다리아의 힘의 상징입니다!"
rows["88:1505235976"]="지구 내부를 바깥으로 보여주는 지구로"
rows["88:1508254404"]="독감된 정신의 카릴은 적들을 향해 던질 수 있는 백색 촉매제를 준비한다!"
rows["88:1530753423"]="길에서 걷고, 내 발을 보고, 잎을 보고, 나무에서 떨어지는 걸 보고"
