rows["88:1587633623"]="이 도전을 받아들일 수 있다면  ⁇ 을 울라. 그렇지 않으면 우리는 이제까지 끝났습니다."
rows["88:1590014595"]="날 걱정 마, 이 끔찍한 짐승을 죽이고 이 세상을 그의  ⁇ 한 손길에서 깨끗하게 해라"
rows["88:159063096"]="아니, 누가 숨어있었는지요. 사우로크 노예들을 데려오세요!"
rows["88:1591204753"]="소 레벨은 없다!... 진짜다! 다시 말한다. 소 레벨은 없다. 뭐... 있을지도 모르고."
rows["88:1597269614"]="그들은 단지  ⁇ 이 있는 사람들의 삶을 위협하는 것이 아니라 모든 살아있는 사람들의 존재를 위협합니다."
rows["88:1611639380"]="내가 널 죽이지 않을 때 내 조직에서 명예로운 자리를 제안해 줄 거야"
rows["88:1613699072"]="이봐, 내가 때려졌어 다음엔 몇 가지 아이디어를 만들어야겠어"
rows["88:1615258484"]="내가 주의를 끌어 보겠소. 형제들을 무덤으로 돌려보내고 나서, 나를 도와주시오."
rows["88:1622887576"]="금속봉 아래 서 있어, 안전해"
rows["88:164199613"]="아, 친절에 감사드리오. 내가 잠시 볼 일을 볼 동안 도서관에서 기다려 주시겠소?"
rows["88:1647385731"]="우리의 힘은 강해졌고, 우리의 적은 다른 적들에게 둘러싸여 계속되는 공격으로 약해졌다."
rows["88:1655040153"]="모든 보상은 워칼러 베어스나우트가 제공하는 서비스입니다.$B$B결제도 안하고"
rows["88:1670230703"]="그대들의 말이 맞소, 정령이여... 그대들에게 그런 짓을 한 것은 나의 동족이었소. 우리가 그 잘못을 바로잡게 해주시오."
rows["88:1681497326"]="그는 이제 네가 알던 이가 아니다, 무라딘. 완전히 다른 사람이 되었단다."
rows["88:168329892"]="최근 이상한 게 눈에 띄었나?"
rows["88:169016401"]="얼라이언스의 영웅들이여, 그대의 왕이 부르노라! 하수구 입구에서 내 뒤로 집합하라!"
rows["88:1692607850"]="집중해 $p야생동물이나 오크 군대의 먹거리는 우리 승무원들을 잘 먹여줄 거야"
rows["88:1699808923"]="이건 바쁜 일인 줄 알았지만, 괜찮아요."
rows["88:170692152"]="티탄 외에 그 누가 그런 저주를 내릴 수 있는가? 무엇이 그런 강력한 힘을 가질 수 있는가?"
rows["88:1713995537"]="좋습니다, 제가 이 장치를 설치하는 동안 절 엄호해 주십시오. 그리 오래 걸리지 않을 겁니다."
rows["88:1716341578"]="이런... 못합니다. 난 가족들이 생각하는 그런 집에 있는 고블린이 아니란 말입니다. 게다가 난 가족들을 이리로 데려오지도 않았다고요."
rows["88:1718531251"]="윌리엄, 언덕에서 신기한 초원이 자라는 걸 봤어."
rows["88:172591691"]="좋아요! 움직입시다. 차량에 올라타세요. 이제부터 무전기로 말씀드리죠."
rows["88:172591704"]="좋아! 출발하자. 기계에 타! 난 여기서 무전기로 이야기할게."
rows["88:1730336662"]="여보. 할란 씨가 가능한 한 빨리 편물 셔츠와 바지 한 짐을 보내 달라는군요."
rows["88:1734574928"]="네, 첸과 리 리처럼 세상 탐험을 하고 있잖아"
rows["88:175012879"]="센리온 서클은 오래전부터 존재해"
rows["88:1752023778"]="내기를 배우고 싶다면 전쟁터 내부 반구에서 브롬 킬리언과 이야기해"
