rows["88:1756731422"]="침입자들을 돌봐주게, 주님. 난 그들의 내장을 벌레에게 먹여줄게"
rows["88:1758154562"]="감사합니다, 친구들 용서해 주세요. 저는 너무 약해져서 도움을 받을 수 없습니다."
rows["88:1761945167"]="기억하세요 $p야생동물이나 적들의 먹거리를 먹으면 제 승무원이 잘 먹어질 거야"
rows["88:1784497182"]="%s 그는 방해된 것처럼 보입니다. 그는 몇 분 동안 상처를 회복합니다."
