rows["88:1828679547"]="듀로타의 비는 폭발점까지 연연, 과열된 가스로 채워집니다."
rows["88:1836759797"]="안 돼... 안 돼! 대체 뭘 한 거냐?! 아까운 고룡 뼈를 망치다니... 대체 무슨 마법이냐?"
