rows["88:1878117290"]="기억하세요, 대사님... 여러분의 사람들이 우리의 노력에 어떤 기여를 할 것인가?"
rows["88:1886033549"]="곧 뿌리를 심고 잠들게 될 거야 내가 쉬기 전에 해야 할 일이 있어"
