rows["88:1902896877"]="내가 칼을 가져갔어야 했지 노스렌드짐은 내 몫이었어\010"
rows["88:1906361199"]="물론 제 물건은 훔쳐지지 않았죠. 하지만 누군가가 물어보면, 당신은 내게서 가져가지 않았습니다!"
