rows["88:2005793912"]="지금까지의 진전을 보고 기쁘네요."
rows["88:2008209739"]="의심하는 사람이라면 빨리 철거해"
rows["88:2046459270"]="호라시 알더가 프라우드무어씨의 탑의 바닥에서 걸어가고 있는 걸 보게 될 겁니다."
rows["88:204883491"]="얼라이언스가 얼음이빨 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!"
rows["88:2052665487"]="시장에서 아이언파우를 만나고 요리 능력을 키우고 싶다면"
rows["88:2055063865"]="난 더 오래 이 방패를 유지할 수 없어 칼리타 우리 중 누구도 이 일을 살아남을 수 있을까?"
rows["88:2057542260"]="이  ⁇ 돌이 너무 쉽게 부패해졌다는 것은 슬프다"
rows["88:2060473677"]="당신들의 실패는 날 지치게 해줍니다. 당신이 지시대로 할 수 없다면 우리는 당신을 위해 쓸모가 없을 것입니다."
rows["88:2066627911"]="네... 얼라이언스... 친구들, 당신들은 꽤나 흥미롭습니다."
rows["88:2069236580"]="고스란히, 우리는 이 짐승이 단지 바깥에 있는 동굴에서 스노우를 하는 걸 잡았습니다."
rows["88:2069488336"]="진록, 제 잔다랄 벤디케이터의 팔지방은 사라졌어"
rows["88:2071304964"]="내가 바쁘면 하루가 빨리 지나간다.$B$B잠시 멈추고 이 순간을 즐기도록 상기시켜야 합니다."
rows["88:208337717"]="극지방의 독특한 자기장 은 수백만 가지 연구 가능성 을 제시 한다!"
rows["88:2086619828"]="카일 씨, 내가 가능한 한 빨리 방을 넘어가려고 노력해... 제발 날 고쳐줘!"
rows["88:2088547826"]="돌난로 참호가 공격받고 있습니다! 저지하지 않으면 얼라이언스에 의해 파괴되고 말 것입니다!"
rows["88:2109503728"]="침묵! 빛 우리를 버리지 않으셨어! 빛 순수한 사람들 가운데 가장 강하도다"
rows["88:2126651786"]="내가 가진 모든 걸 줄게, 캡틴"
rows["88:2128791317"]="넌 위험해 난 악마들을 불러내는 것에 만족하지만"
rows["88:2132419206"]="또한, 도로리아 여인의 불결한 얼굴에 빛나는 빛을 비추기를 부탁드립니다."
rows["88:2146217431"]="왜 먼저 미르베돈에게 가서 실력을 키우지?"
rows["88:217898383"]="이 계곡을 보호하는 어떤 장벽이 있어 포털 마법을 사용하지 못하게 해"
rows["88:221171936"]="다  ⁇ 다라리라는 다 더크스피어스를 포함한 모든 트롤 부족들을 모집했습니다. "
rows["88:223923161"]="왜인지 모르겠지만, 그 괴물은 우리 사람들을 살려줄 수 있는 모든 노력을 하고 있습니다."
rows["88:232867052"]="안두인, 누구보다 더 잘 알고 있는 건, 호드를 그 사람들로부터 분리하는 것이 중요합니다."
rows["88:251530200"]="우리가 움직일 때, 우리는 빨리 움직일 것입니다. 우리의 길을 걸을 모든 것을 휴식 할 준비가 되십시오."
rows["88:256172750"]="끝났지만 여기서 오래 머물지 않아서 캠프 동쪽 끝에 만나게 되"
rows["88:256311494"]="다 끝났소. 담아야 할 것을 모두 담았어. 이제 용의 영혼을 영원히 봉인하겠소."
rows["88:262356112"]="하지만 물론 위험합니다. 이 유물의 비밀은 우리에게 쓸모가 없을 것입니다."
rows["88:28281735"]="그 구형의 얼굴을 보고 싶네요, 그가... 뭐?"
rows["88:282818226"]="그리파, 네 코가 너무 날카로운데 행운의 냄새도 안 들리는데"
rows["88:287022122"]="루리엘이 도와줄 줄 알았어요! 감사합니다, 친구여. 루리엘에게도 고맙다고 전해주세요!"
rows["88:290886986"]="준비되면 젠키에게 알려줘서 이 새들 중 하나를 가져오겠다"
rows["88:29827546"]="블러드 라이트 노엘레네는 광장의 동북부 건물 안에 젊은 연습생들을 기다리고 있습니다."
rows["88:30580133"]="세상이 끝날 때라면, 이 종파들은 정말로 우리를 경고하는 것에 신경을 쓸 것 같습니까?"
rows["88:308105258"]="당신들의 땅에서 그들을 몰아내는 데 도움이 되세요 호드!"
rows["88:30878481"]="셀 수 없을 정도로 많은 해가 서는 동안, 이 얼음의 땅에는 다드족이 살고 있습니다."
rows["88:309291383"]="판다리아의 모든 동맹들은 검을 쏘아 이길 수 없다는 것을 기억하세요."
rows["88:311870983"]="고대의 해적 Dice를 조심스럽게 던집니다. dice는 떨어지고 7로 이어집니다. 아무 일도 일어나지 않습니다."
rows["88:312187663"]="어떤 버그가 의회의 사장들 앞에 나오는가?"
rows["88:314835195"]="절망적인 클라크시들은 화석들을 발굴하는 데에 돌입했습니다."
rows["88:319854203"]="목걸이가 호수에서 떨어졌어 아빠가 내게서 가져왔어"
rows["88:320376867"]="수고했어요! 당신의 도움이 없었으면 트로그 침략 부대를 절대 막을 수 없었을 거예요."
rows["88:324560172"]="군대를 모은 후에 돌아올 거야"
rows["88:324827809"]="잠깐! 우린 친구 아냐 하지만 낯선 지역에 혼자 가서는 안 돼"
rows["88:337852069"]="이런 일로 너무 흥분하지 마시오, 영웅 친구. 지금까지의 일은 쉬운 부분이었소. 앞으로 험난한 과정이 기다리고 있으니 어서 갑시다!"
rows["88:340075510"]=" ⁇ 소 입자 효과에 대한 감시, 구매 시간 탐사에서 완료 이벤트를 구현하기 위해."
rows["88:363743736"]="<아동은 마치 당신이 그 엄마인지 아닌지를 결정하려고 하는 것처럼 당신을 쳐다봅니다.>"
rows["88:36640936"]="제니, 우리 사이에 관계가 있다고 생각했는데"
rows["88:371392678"]="내 피를 보려고 기를 쓰는구나! 하지만, 아직 멀었다... 네 녀석이 없애야 할 건, 내 머리다!"
rows["88:375953363"]="만약 당신이 그것을 할 용기가 있다면, 불모의 땅에서 좋은 사냥을 찾을 수 있습니다."
rows["88:377974369"]="그 드루이드들이 지금 아이들을 죽게 보내야 하는 거야?"
rows["88:381372133"]="그 오그르는 전쟁이 임하고 있다는 첫 신호입니다. 과일의 판매자는 너무 멀리 갔습니다."
rows["88:385524005"]="동상의 이 부분은 주체가 실제로 팔을 가지고 있었다는 것 외에는..."
rows["88:394258166"]="화려한 칼이 그림자 협의회가 실패한 곳을 차지하는 것이 좋았습니다."
rows["88:395439087"]="부하들이 무엇이길래요! 그 무엇도 내 복수를 막을 순 없습니다! 오랜 친구인 당신조차도요..."
rows["88:403177029"]="이 작은 임무에 더 이상 자격을 갖춘 것 같아요. 내가 옳는지 보자!"
rows["88:416409769"]="고통은 순간적이고, 대령이 내게 해준 것과 비교해"
rows["88:420723525"]="세 번 잠금된 구석의 셋째 잠기는 클릭하고 땅에 떨어집니다."
rows["88:44394980"]="|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s 캐스팅 |cFF00FF00매일러블 구!|r"
rows["88:445096841"]="내 사업에서 신중함이 중요해요"
rows["88:45291445"]="모든 사람이 자리를 잡으세요! 적들이 우리 주변을 둘러싸고 있습니다. 시간 낭비할 시간이 없습니다."
rows["88:454594390"]="마이클 가렛이 언더시티상류구역의 상위 반에 있습니다."
rows["88:45835480"]="너무 화가 났어, 사로크? 너무 많이 마시지 마..."
rows["88:462587150"]="|cFFFF2222[라이트닝 랜스] |r는 충전되어 있습니다. 그것을 사용하여 샤 아말가메이션을 완료하십시오!"
rows["88:465675694"]="잘했어 $p이 섬의 크리스탈은 키린 토르보다 우리 손에 더 잘 있어요"
rows["88:476662485"]="내 방어력이 승리한 것 같네요. 다시 시도할 준비가 되면 나와 이야기해 주세요."
rows["88:477786243"]="라저힐 동쪽에 있는 바락 안에 하나 있어요"
rows["88:481583919"]="난 당신과 이 배신적인 스톤브레이커 지휘관이 내 아들의 자권을 훔치도록 허락하지 않을거야!"
rows["88:508965493"]="고블린 레이저는 많은 펀치를 가지고 있지만,  ⁇ 은 놈들은 차에  ⁇ 을 두 가지 숨겼습니다."
rows["88:512892743"]="침입자들을 해치워라, 더러운 넝마두건 녀석들아! 내 말을 거역한다면 끝없는 고통을 선물해 주마!"
rows["88:515802823"]="당신이 원하는 대로, 우리는 당신의 유물을 찾을 것입니다. $p - 스라'틱 침투에서 만나게 될 거야"
rows["88:523433398"]="사실 그렇게 나쁘지 않네, 그럼 내가 좀 할래?"
rows["88:527152992"]="죽음 날개를 섬기는 것은 사실이지만, 더 높은 힘도 섬기게 됩니다."
rows["88:528898368"]="우리가 수영장을 조사하는 동안, 우리는 도시의 국경에 순찰하고 이 사람들을 보호할 것입니다."
rows["88:532922845"]="다크월 페어가 다가오고 있습니다. 모든 연령대의 어린이들이 재미있게 놀고 있습니다."
rows["88:535617438"]="위대한 자들이 안전하게 집 지켜줬어. 점쟁이 조합을 좋아하기 때문이라고 생각해! 우리가 착하고 괜찮다는 걸 아니까."
rows["88:53758930"]="이 로켓은 먼 곳에 있는 배드랜드까지 데려갈 거야"
rows["88:537952594"]="세상에, 림피 조를 죽이고 고기를 가져오다니! 우리가 여기 있는 줄은 어떻게 알았소?"
rows["88:54593079"]="빨리 해봐, 시간이 오래 걸리면 더 큰 상처를 입게 될 거야!"
rows["88:546543152"]="거기 있는 동안, 지혜로운 늙은 전쟁 영웅이 내게 영원히 가지고 갈 것을 말했다..."
rows["88:560595180"]="나 이 금빛 물고기에 대한 얘기를 들은 적이 있어. 이걸 잡으면 세 가지 소원을 들어 준대!"
rows["88:563198179"]=" ⁇ 다라리족은 내가 생각했던 것보다 더 조심스럽고"
rows["88:564413287"]="당신의 설교를 듣는 동안 강한 느낌을 받았습니다. 그 느낌이 날 괴롭히고 있단 말입니다!"
rows["88:590628579"]="자넨 스스로 도와줘 스카우트가 날 너무 무겁게 돌리는 것은 자살이야"
rows["88:595894727"]="매일 마음 속 에서 희망 을 가지고 살아라. 그렇게 함 으로, 당신 은 꿈꾸는 미래 를 창조 한다."
rows["88:597460866"]="메슬리 여인은 테라모어에 있을 만큼 승객들을 지키도록 할당됐습니다."
rows["88:61192679"]="[%s한 번 마법을 던진 거 봤는데 제 턱은 정말 손상으로 떨어졌어요"
rows["88:615499657"]="이 끔찍한 장소에 오래 있으니 시간 감각마저 없어지더군요. 당신이 얼마나 반가운지 모릅니다, 친구여."
rows["88:615982892"]="두 가지 모두 호드 그리고 얼라이언스 캡틴들이 쓰러졌어, 너무 늦기 전에 드렉 타르를 물리치세요!"
rows["88:631196858"]="죽음의 날개는 나 Tarecgosa의 배에 직면할 준비가되었습니다. 당신의 바보 여행은 여기서 끝납니다!"
rows["88:644986338"]="조심해, 동맹군, 우리 침입으로부터 불의 주인들을 보호하기 위해 함정이 있을 겁니다."
rows["88:652329106"]="내 뒤에서 나오는 이 똥구리한테 신경 쓰지 마"
rows["88:655178174"]="스톰파이크 보급기지가 공격받고 있습니다! 저지하지 않으면 호드에게 넘어갈 것입니다!"
rows["88:667254524"]="당신은 특별한 일을 해냈어요, 군인! 기병대는 당신의 명령에 따라 타고 갈 준비가 되어 있습니다."
rows["88:670488684"]="너희 둘은 많은 승하와 하락을 겪겠지만, 견딜 수 있다면, 그 여행이 가치가 있을 것이다."
rows["88:675242587"]="여기 우리 첫 번째  ⁇ 이 있는 건 봐요"
rows["88:703905911"]="아주 좋은 임무야, 하지만 \"만치 않고 만지지 않는 것\"은 시간이 지나면 오래되고"
rows["88:730504304"]="우린 영원히 숲에 있는 것처럼 느껴지네, 가자, 골짜기를 탐험해야 해"
rows["88:74516095"]="응보의 날이 다가왔다! 암흑이 적들의 마음을 지배하리라!"
rows["88:747440562"]="울고 있는 영혼을 잡을 때마다 그림자 속임수를 받을 수 있을 거야"
rows["88:747591103"]="노스렌드가 척박한 땅인 것은 분명하지만, 우린 강인하고 굳센 사람들이니 충분히 이 일을 해낼 수 있소!"
rows["88:770072664"]="우린 할 수 있는 모든 걸 해냈어, 가오랑, 내가 할 수 있는 대로 더 많은 사람들을 보내겠다."
rows["88:77042302"]="너희들은 스스로 강하다고 생각해야 한다. 얼마나 잘 알지 못하니."
rows["88:77308850"]="돌난로 무덤이 공격받고 있습니다! 저지하지 않으면 호드에게 넘어갈 것입니다!"
rows["88:77668340"]="난 당신에게 맹세합니다. 나는 이 세상을 앞으로의 전투에 준비하기 위해 아무것도 멈추지 않을 것입니다."
rows["88:77770901"]="이번 회의에 동의했지, 세계적 파괴자."
rows["88:800631182"]="형제, 우리 방어에 주의를 기울여야 합니다. 얼라이언스 동쪽에서 우리를 침략하고 있습니다."
rows["88:808584300"]="타레타가 살아있어서 다행이야 이제 마법의 구속에서 벗어나야 해"
rows["88:808864325"]="서둘러 움직여야 하네. 아우버다인은 그리 멀지 않지만 많은 적들이 숲에서 잠복하고 있네."
rows["88:814409648"]="저들이 지하묘지에서 뭔가 부정한 의식을 진행하고 있어요. 그 의식에 제가 곧 제물로 바쳐질 겁니다!"
rows["88:814713346"]="나머지 드레이크는 곧 도착할 겁니다."
rows["88:819498283"]="우리를 버렸다는 것을 지불할 겁니다."
rows["88:820066217"]="공식 탐험가 리그 문제, 맥고이버 탐험가 리그 우포스트로 데려다줘"
rows["88:830316620"]="이 마을에 있는 작은 보라색 생물의 정체가 뭔지 궁금합니다... 정말 아름답거든요."
rows["88:831678709"]="늦지 마, 그는 거의 여기 있어요!$B$B북쪽 탑 꼭대기에 만나자"
rows["88:837172074"]="신전의 수호자들이 더는 존재하지 않습니다. 신전에서 자라던 식물들은 죽었습니다."
rows["88:83803706"]="어떡해, 가족 요리법을 모르면 어떻게 가족  ⁇ 거리를 운영할 수 있을까?"
rows["88:842250936"]="어리석은 필멸의 생명체들아, 내가 너희의 죄를 그냥 둘 줄 알았느냐?"
rows["88:847867581"]="에스코다르의 가죽 노동자들을 트레이더의 차원에서 찾을 수 있습니다. 빛 - 안녕하세요"
rows["88:852485468"]="오르도 워브링거가 죽었다고 말해줄래?"
rows["88:857793269"]="내가 떠나서 내 새끼를 공격할 용기가 있는 겁쟁이?"
rows["88:866125899"]="또 다른 낯선 사람? 당신 같은 사람 들 은 좋은 맥주 를 즐겨 먹으십니까?"
rows["88:867371137"]="어떻게 그 괴물이 이렇게 잔인하게 할 수 있었을까요?"
rows["88:86914543"]="침입자야, 이 상자에 있는 유물이 뭘 할 수 있는지 보자"
