rows["88:959166074"]="곧 그 구석이 공허하고 희생은 완전해지고 당신은 다른 자리를 차지할 거야"
rows["88:963272287"]="그 배고픈 눈으로 보는 모습은, 내가 뒤집을까봐 무서워"
rows["88:985629847"]="넌 성공했어! 믿을 수 없어! 판다렌 로어워커들은 네 이야기를 세대를 넘게 들려줄 거야!"
