rows["88:991505082"]="비라 영하프는 마을 서쪽에 있는 긴 집 안에 자신의 연습을 하고 있습니다."
rows["88:995590114"]="오케이 트롤에 대한 이야기를 좋아했어 다른 얘기가 있어?"
