rows["89:1030666517"]="%s 초청하기 시작 |cFFFE9A2E불꽃 연동성 유신|r불꽃벽을 막기 위해 그들을 물리치세요!"
rows["89:1032121546"]="시민 여러분, 곧 물가 우리를 위해 변하고 전염병이 끝날지도 모릅니다."
rows["89:1060809323"]="이 책은 나에게 모든 적을 능가하는 무한한 힘을 줄 것이다... 난... 무적이 될 거야!"
