rows["89:1229458720"]="뻔한 놈들! 하긴, 돌 따위가 그보다 낫기를 기대한다는 게 무리지!"
rows["89:1245356914"]="[우측 클릭] |cFFFFFFFF에 부상자 스톰윈드 보병 당신은 북쪽 필드에서 찾을 수 있습니다.|r"
