rows["89:1359679965"]="우린 남쪽으로 계속 가야 돼, 상가 광장에 돌아갈 수 없어"
rows["89:1361371823"]="이 유감스러운 부족들은 당신보다 낮아 우리 민족의 위대한 유산을 훼손하고 있습니다!"
