rows["89:1442032053"]="내가 분노해 휘두른 칼에 맞으면 안 되니까 변장을 풀도록 하게."
rows["89:1446474074"]="그들은 잘 속이는 법을 가르쳐줍니다. 언더시티의 외곽 반지의 로그스 구내에서 발견됩니다."
rows["89:1455312239"]="밸라스트라즈여, 이 세계가 검은용군단의 손아귀에 떨어지는 그날, 너의용군단은 멸망을 피하지 못할 것이니라!"
