rows["89:1460965218"]="그들은 불성스러운 의식들을 대묘에서 수행하고 있고, 저는 희생자가 될 것입니다!"
rows["89:1461903934"]="호드 경비탑이 모두 무너졌다! 이제 놈들은 힘을 잃었다. 잔병을 처리해라!"
