rows["89:1565926824"]="이 시대는 아무리 힘들지만, 우리는 우리의 감정을 통제해야 합니다."
rows["89:1575307603"]="오타 웬, 들어봐요, 오크들에게 맞서야 해요!"
rows["89:1588161273"]="단순히 답을 제공하는 것은 아무것도 가르치지 않습니다.$b$b판다리아는 교육과 학습의 땅입니다."
rows["89:1588646158"]=" ⁇ 페스트의 티차리 우두 맥주 공장으로 가서 부드러운 음료를 마시세요"
rows["89:1599559617"]="우리는 새로운 호드, 그리고 Warchief Hellscream 아래, 우리는 우리의 운명의 주인입니다."
rows["89:1610784348"]="넌 내 일을 위협해줘서 다 ⁇ 한 흉터가 부활했어"
rows["89:16190400"]="내 직종의 한 여자가 배고프면 좋겠어"
rows["89:162163241"]="그래, 상대해 주지. 그런데 시작하기 전에 먼저 너희가 만나볼 친구가 있다."
rows["89:1627358672"]="잠든 성전은 동쪽 슬픔의 습지의 큰 호수의 중심에 있습니다."
rows["89:1643145549"]="이제 그들이 말하길 그 지도를 손에 넣을 수 있는 사람은 잃어버린 보물을 찾을 수 있다고..."
rows["89:1648368900"]="자, 자, 다음 경주에서 돈을 따려면 노움에게 거세요! 기회가 있을 때 어서 참여하세요!"
rows["89:1673201415"]="조금 걱정이 되는걸. 이 전투에서 우리를 이끌기로 한 영웅은 대체 어디 있는 거지?"
rows["89:1674445306"]="당신 같은 사람이 있었는지 알고 있었는데 Vol'jin라는 이름이었죠"
rows["89:1698240184"]="이제 한 단계 높여서 비밀 재... 재... 재 뭐더라... 비밀 양념을 뿌리는 거지!"
rows["89:1751508697"]="카엘타스와 일리던과의 싸움은 모든 전선에서 계속되고 패배는 선택의 여지가 없습니다."
rows["89:1775996690"]="그래, 가족 속의 일인데 디그송은 항상 떠기 문제였어"
rows["89:178250718"]="캔디, 그게 내가 말하는 거야, 그냥 찾아다니지 않아도 돼!"
rows["89:1783381841"]="정말 도움이 되고 싶다면 저와 제 친구들에게 전투 연습을 할 수 있습니다."
rows["89:1783997607"]="다리우스, 암흑 경호가 스카이스를 잡았어"
rows["89:1791788241"]="우리 나라를 어둠으로 삼은 악에 굴복해서는 안 됩니다."
rows["89:1791862670"]="그래서 당신은 얼라이언스의 챔피언이라고 불리는 사람이고 당신의 죽음으로 이 곳은 쉽게 무너질 것입니다."
rows["89:1802876503"]="개개는 북쪽에서 냄새를 맡고 기원에 달려갈 준비를 하고 있습니다."
rows["89:1804585192"]="이 지역은 모두 알고 있어, 새로운 얼굴이 생겼다고 알려줄게"
rows["89:180967645"]="내가 만든 최신 발명품으로 너희들을 모두 이길 거야"
rows["89:1823360747"]="이 약이 효과가 있더라도... 우리 마을에서 워겐이 미쳤을 수는 없어, 크레넌"
rows["89:1823451372"]="호드가 얼음이빨 광산을 점령했습니다! 광산의 자원이 군사력을 키우는 데 쓰일 겁니다!"
rows["89:1828709243"]="드레노르에서 그는 불행한 비참자였고 아버지의 행동이 그의 마음에 걸려있었다."
rows["89:1833312187"]="조사하는 중입니다, 와플프라이 씨. 뭐 다른 할 일 없으신가요? 새로운 기계 장치를 시험해 봐야 한다든가..."
rows["89:1835402136"]="그래, 점쟁이가 너를 돕기로 했다는 말이구나, 이방인. 좋다, 내가 아는 걸 말해 주마."
rows["89:183867838"]="바닥에 서 숨어서, 문제가 생기면 다시 이리로 데려다 줄게!"
rows["89:1845099167"]="그 곳 - 당신은 그것을 느끼는가? 영혼의 완벽한 조용! 꿈의  ⁇ 이 효과를 느낄 수 있다."
rows["89:1848652639"]="힘과 용기를 혼동해, 어린 드래곤."
rows["89:1855691679"]="안전해요, 얼마 전 로어워커 쇼와 그의 이상한 동료들을 이리로 데려왔어요"
rows["89:1858876899"]="현존하는 모든 노동자들에 대한 대가를 받고 있습니다."
rows["89:1868617930"]="브로하이 (Brojai) 는 모가와 협상할 의도가 없다는 것을 분명히 했습니다."
rows["89:18720490"]="당신이 찾는 아치발드, 전쟁터 내부의 무기 상점 밖에 있는 놈"
rows["89:187255580"]="%s은 토테마에서 에너지를 소파하고 반 마법의 충동으로 다시 방향을 전환합니다."
rows["89:1880229610"]="상위 3위는 여전히 인상적이지만, 상위 절반은 하위 절반보다 낫죠?"
rows["89:1897815437"]="오크들은 우리를 미워하고, 오바데이!"
rows["89:1903005956"]="오늘의 검은 운명은 앞으로 더 많은 날에 이어지리라. 이것은 비극의 시작일 뿐, 끝은 다른 이들이 맺어야 한다."
rows["89:1908615226"]="아마도 비밀결사대의 다른 대원들일 걸! 넌 절대 알터랙이나 남녘해안으로 돌아가지 못해!"
rows["89:191530399"]="아즈하리트, 너흰 부드러운 놈들이 모든 것에 새로운 이름을 내놓는 거야"
rows["89:191955675"]="센진 마을의 트롤들은 미아잔이라는 술조사를 가지고 있다고 들었어요"
rows["89:1921186635"]="이 곳은 가득 차 있어, 우리 모두 팀을 꾸려 바리안의 얼굴에 발자취해야지!"
rows["89:1922896743"]="황폐의 침략자, 불타는 칼에 합류하거나 저항의 결과를 겪으십시오!"
rows["89:192361799"]="죽은 자들은 흠이 아제로스너희 모든 생명체는 파괴를 받을 자격이 있어!"
rows["89:1930754288"]="대장 가죽공인 다마리는 하위 도시의 시장에서 발견 될 수 있습니다."
rows["89:1940218627"]="우리 는 그 들 에게 더 강력 한 사람 이 누구인지를 결정 하기 위해 형제 를 싸웠다."
rows["89:1946033209"]="내가 할 수 있는 모든 것을 근처의 잔해에서 구해냈지만, 난 너무 오래 내려서..."
rows["89:1951627905"]="이 무신한 독성성 쟁이를 통과해야 살아서 빠져나와야 돼!"
rows["89:1952915323"]="키린이 널 그 농장으로 보내준 거야?"
rows["89:1977679433"]="제발 상자를 가져가라, 난 이미 타워 도서관에서 뭘 찾을까 생각 중이야!"
rows["89:1982279028"]="이 리치 왕 더 열심히 일하면 우스꽝스러운 놈들이 돼서 먹여줄 거야"
rows["89:1985635016"]="다른 사람들을 불러서, 헬스크림을  ⁇ 게 해 호드 그리고 그들의 시체를 바다로 던져버립니다."
rows["89:1989084657"]="지금 당장 건설자들을 보내야 할 겁니다."
rows["89:2005031335"]="친구나 가족들과 다시 만나고, 옛날 이야기를 나누는 것이 좋죠."
rows["89:2017435229"]="쓰러지는 전사 하나하나가 우리 위대한 군대의 병사가 된다. 우리를 상대로 승리란 없다."
rows["89:2020734079"]="적을 향해 진전할 준비를 해줘서 배신자한테 총격 공격이 곧 시작될 거야"
rows["89:2030836342"]="녹색 엄지손가락과 철강 엄지손가락이 있는데 아빠가 모든 것을 다듬는 법을 가르쳐줬어요"
rows["89:2037049909"]="네가 뭘 했냐가 아니라, 네가 누구냐는게 중요한데"
rows["89:2037890675"]="- 뭐하고 싶은데?$B$B이유 없이 낯선 사람에게 다가가는 건 좀 무례한 것 같네?"
rows["89:2042233262"]="오, 브라보. 이 형편없는 실패작을 풀어주고 나니 좀 뿌듯하신가?"
rows["89:2045139722"]=" ⁇ 을 들었어? 바람에 계속 소리를 듣는다. 나쁘지 않아. 전혀 좋지 않아."
rows["89:2046515916"]="키라지들이 괴물들을 먹이는 걸 알아내야 돼"
rows["89:2076540208"]="내 가문들과 죽음 사이에 서 있는 이 무지한 짐승들을 돌보는 것은 영광입니다."
rows["89:2078309011"]="그러니까 내가 어떤 거대하고 오래된 나무가 있는 산에 있었습니다. 주위에는 엘프들이 여기저기 뛰어다니고 있었고요..."
rows["89:2087201542"]="왜 우리가 당신 공격할 때까지 기다리지 않는가? 오그리마그리고 죽은 사람을 닦아?"
rows["89:2089634810"]="어쩌면 내가 나의 회사를 받을 만한 모험가를 만났을지도 모른다. 아마도 당신은 내 사람들을 구출할지도 모른다."
